with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la Llei 13/2008, de la presidència de la Generalitat i del Govern, qui determina el nombre, la denominació i l''àmbit de competències dels departaments?', 'L''art. 23.2 de la Llei 13/2008 ho atribueix al president per decret; la Presidència constitueix en tot cas un departament.', 'bomb_t01_constitucio_estatut_generalitat', (select id from public.topics where slug = 'bomb-t01-constitucio-estatut-generalitat'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2008-19526'), 'Art. 23 Llei 13/2008', 'El presidente o presidenta de la Generalidad determina por decreto el número, la denominación y el ámbito de competencias de los departamentos en que se organiza el Gobierno.', null, 'ab0e5bbc496d140de32d63d2b53d7a18fea32fe20920cf15a8251b5510abc57e', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'ab0e5bbc496d140de32d63d2b53d7a18fea32fe20920cf15a8251b5510abc57e')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El Govern, per acord.', false), ('B', 'El president o presidenta de la Generalitat, per decret.', true), ('C', 'El Parlament, per llei.', false), ('D', 'Cada conseller o consellera, per ordre.', false)) as v(label, body, ok)
)
