  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la Llei 17/2015, què és l''assetjament sexual?', 'Art. 2.p de la Llei 17/2015. L''assetjament per raó de sexe (art. 2.o) no requereix naturalesa sexual del comportament.', 'bomb_t04_igualtat_no_discriminacio', (select id from public.topics where slug = 'bomb-t04-igualtat-no-discriminacio'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-9676'), 'Art. 2 Llei 17/2015', 'Acoso sexual: cualquier comportamiento verbal, no verbal o físico, de naturaleza sexual, que se ejerce con el propósito o efecto de atentar contra la dignidad de una persona, especialmente si le crea un entorno intimidatorio, hostil, degradante, humillante u ofensivo', null, '62e2339838ed9dfacc29dd6024c7f6f00b2d1b1930b6501754efaaba25b0cd1e', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '62e2339838ed9dfacc29dd6024c7f6f00b2d1b1930b6501754efaaba25b0cd1e')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Qualsevol comportament que, per raó del sexe d''una persona, atempti contra la seva dignitat.', false), ('B', 'Només les conductes físiques de naturalesa sexual.', false), ('C', 'Qualsevol comportament verbal, no verbal o físic de naturalesa sexual que atempti contra la dignitat d''una persona, especialment si li crea un entorn intimidatori, hostil, degradant, humiliant o ofensiu.', true), ('D', 'Qualsevol instrucció que impliqui discriminació per raó de sexe.', false)) as v(label, body, ok)
)
