  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Com defineix el manual de teoria del foc el punt d''inflamació (flash point)?', 'En el punt d''inflamació la flama apareix però no es manté; el punt de combustió és el que la manté; l''autoignició no necessita font externa.', 'bomb_t08_teoria_foc_agents_extintors', (select id from public.topics where slug = 'bomb-t08-teoria-foc-agents-extintors'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-08-MAN.GRAL.008.pdf'), 'MAN.GRAL.008, § punt d''inflamació', 'És la temperatura mínima a la qual un combustible emet prou vapors per formar una barreja inflamable amb l''aire, que pot encendre''s momentàniament en presència d''una font d''ignició externa (una flama, una guspira, etc.).', null, 'ce703150086b7f2f5033dbbb2b5aad40381d680abba358bf0cf91b4cf13764b4', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'ce703150086b7f2f5033dbbb2b5aad40381d680abba358bf0cf91b4cf13764b4')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La temperatura a la qual un combustible s''encén espontàniament sense cap font d''ignició externa.', false), ('B', 'La temperatura mínima a la qual un combustible manté la flama de forma continuada.', false), ('C', 'La temperatura mínima a la qual un combustible emet prou vapors per formar una barreja inflamable que pot encendre''s momentàniament amb una font d''ignició externa.', true), ('D', 'La temperatura a partir de la qual un sòlid comença a fondre''s.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('bombers-generalitat');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual de teoria del foc, quina relació hi ha entre el punt de combustió i el punt d''inflamació?', 'El punt de combustió és uns pocs graus més alt que el d''inflamació perquè cal una generació de vapors més sostinguda per mantenir la flama.', 'bomb_t08_teoria_foc_agents_extintors', (select id from public.topics where slug = 'bomb-t08-teoria-foc-agents-extintors'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-08-MAN.GRAL.008.pdf'), 'MAN.GRAL.008, § punt de combustió', 'El punt de combustió és sempre lleugerament superior al punt d''inflamació (normalment uns pocs graus més alt), ja que requereix una generació de vapors més sostinguda per mantenir la flama activa.', null, '839d6ee9dd69eb695c6da3039d5c9a04b0fa66ca821bbf209ecd4caec4614f43', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '839d6ee9dd69eb695c6da3039d5c9a04b0fa66ca821bbf209ecd4caec4614f43')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El punt de combustió és sempre lleugerament superior al punt d''inflamació.', true), ('B', 'El punt de combustió és sempre inferior al punt d''inflamació.', false), ('C', 'Tots dos són sempre idèntics.', false), ('D', 'El punt de combustió coincideix amb el punt d''autoignició.', false)) as v(label, body, ok)
)
