  select 'Segons el manual de teoria del foc, què implica que una substància tingui un rang d''inflamabilitat més ampli?', 'Com més ampli és l''interval entre l''LII i l''LSI, més concentracions de la barreja amb aire poden cremar o explotar.', 'bomb_t08_teoria_foc_agents_extintors', (select id from public.topics where slug = 'bomb-t08-teoria-foc-agents-extintors'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-08-MAN.GRAL.008.pdf'), 'MAN.GRAL.008, § rang d''inflamabilitat', 'Com més ampli sigui aquest rang, més gran és el risc que la substància formi una barreja perillosa amb capacitat d’encendre’s.', null, 'e4acb57b474d189aeebddebf268032e459f26e5a65bb83d820eeb1a59c4720d7', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'e4acb57b474d189aeebddebf268032e459f26e5a65bb83d820eeb1a59c4720d7')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Que és més difícil que s''encengui.', false), ('B', 'Que hi ha més risc que formi una barreja perillosa capaç d''encendre''s.', true), ('C', 'Que només pot cremar en atmosferes enriquides d''oxigen.', false), ('D', 'Que la seva temperatura d''autoignició és més baixa.', false)) as v(label, body, ok)
)
