  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual de teoria del foc, a quina classe pertanyen els focs d''olis i greixos d''origen animal o vegetal en aparells de cuina?', 'La classe F (abans classe K en altres normes) agrupa els focs d''olis i greixos de cuina, que requereixen agents que actuen per saponificació.', 'bomb_t08_teoria_foc_agents_extintors', (select id from public.topics where slug = 'bomb-t08-teoria-foc-agents-extintors'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-08-MAN.GRAL.008.pdf'), 'MAN.GRAL.008, § classe F', 'Focs derivats de l''ús d''olis i greixos d''origen animal o vegetal en aparells de cuina (restaurants, cuines industrials).', null, '802c0af1bd6e5c7417dbc18837278e88137e59c1af15f7be49fd527848c3711e', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '802c0af1bd6e5c7417dbc18837278e88137e59c1af15f7be49fd527848c3711e')
  returning id
), o as (
