with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual de teoria del foc, de què està composta principalment la pols química polivalent ABC?', 'La pols ABC és principalment fosfat monoamònic; la pols convencional BC sol estar basada en bicarbonat de sodi o potassi.', 'bomb_t08_teoria_foc_agents_extintors', (select id from public.topics where slug = 'bomb-t08-teoria-foc-agents-extintors'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-08-MAN.GRAL.008.pdf'), 'MAN.GRAL.008, § pols ABC', 'Està composta principalment per fosfat monoamònic.', null, 'd93cbf065c1899d74624ac8d9706445f6b8ef1054253b2d541350e1a19344daa', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'd93cbf065c1899d74624ac8d9706445f6b8ef1054253b2d541350e1a19344daa')
  returning id
), o as (
