with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual de teoria del foc, quins senyals poden indicar la possible presència d''un backdraft en un compartiment tancat?', 'El backdraft es dona en incendis amb ventilació limitada; el fum espès, marronós o groguenc i pulsant n''és un senyal. La ignició simultània de totes les superfícies és el flashover.', 'bomb_t08_teoria_foc_agents_extintors', (select id from public.topics where slug = 'bomb-t08-teoria-foc-agents-extintors'), 3, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-08-MAN.GRAL.008.pdf'), 'MAN.GRAL.008, § backdraft', 'L''acumulació de fum espès i sense moviment, de color marronós o groguenc, juntament amb “respiracions” a les escletxes (fum pulsant), són senyals de la seva possible presència.', null, '6e5ebce179e783ff96b1f336422efdf63420fbde5dc05a2d814d0ddca03cd095', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '6e5ebce179e783ff96b1f336422efdf63420fbde5dc05a2d814d0ddca03cd095')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Flames que surten a gran velocitat per les finestres i fum blanc i lleuger.', false), ('B', 'Ignició simultània de totes les superfícies combustibles de la sala.', false), ('C', 'Fum espès i sense moviment, de color marronós o groguenc, i «respiracions» a les escletxes (fum pulsant).', true), ('D', 'Fum negre ascendent amb gran turbulència i absència de calor a les portes.', false)) as v(label, body, ok)
)
