with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Quina de les afirmacions següents descriu el flashover segons el manual de teoria del foc?', 'El flashover és la generalització de l''incendi a tota la sala per la radiació i la convecció dels gasos calents. La reignició per entrada d''aire és el backdraft i l''ebullició de l''aigua sota el combustible, el boil-over.', 'bomb_t08_teoria_foc_agents_extintors', (select id from public.topics where slug = 'bomb-t08-teoria-foc-agents-extintors'), 3, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-08-MAN.GRAL.008.pdf'), 'MAN.GRAL.008, § flashover', 'Flashover El flashover és la transició ràpida d''un incendi localitzat a un incendi totalment desenvolupat en un espai, on totes les superfícies combustibles s''encenen gairebé simultàniament.', null, '3cadc0d0bb168476dbdd6aac70aa612c3699892037d0a4fea0a78b02a5372f67', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '3cadc0d0bb168476dbdd6aac70aa612c3699892037d0a4fea0a78b02a5372f67')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Una reignició explosiva provocada per l''entrada sobtada d''aire en un compartiment amb ventilació limitada.', false), ('B', 'L''ebullició sobtada de l''aigua acumulada sota un combustible líquid que projecta el combustible fora del recipient.', false), ('C', 'La transició ràpida d''un incendi localitzat a un incendi totalment desenvolupat, en què totes les superfícies combustibles s''encenen gairebé simultàniament.', true), ('D', 'La ruptura d''un recipient que conté un líquid a pressió per sobre del seu punt d''ebullició.', false)) as v(label, body, ok)
)
