with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual de teoria del foc, a partir de quin coeficient d''expansió es parla d''escuma d''alta expansió?', 'Baixa expansió: fins a 20:1; mitjana: de 20:1 a 200:1; alta: més de 200:1, per omplir grans espais tancats.', 'bomb_t08_teoria_foc_agents_extintors', (select id from public.topics where slug = 'bomb-t08-teoria-foc-agents-extintors'), 3, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-08-MAN.GRAL.008.pdf'), 'MAN.GRAL.008, § escumes per coeficient d''expansió', 'Alta expansió (més de 200:1):', null, '8da51499b8a0638d2192b8e3a816a57e0a6ba7b618bfe6a249a5498ad7bd2882', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '8da51499b8a0638d2192b8e3a816a57e0a6ba7b618bfe6a249a5498ad7bd2882')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Més de 20:1.', false), ('B', 'Més de 100:1.', false), ('C', 'Més de 1.000:1.', false), ('D', 'Més de 200:1.', true)) as v(label, body, ok)
)
