)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('bombers-generalitat');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual de teoria del foc, a quins nivells d''oxigen es dissenyen normalment els sistemes d''extinció per gasos inerts per permetre una exposició humana curta i segura?', 'Els gasos inerts extingeixen reduint l''oxigen fins al 10-12,5 %, nivell que permet l''evacuació sense els efectes tòxics directes del CO₂.', 'bomb_t08_teoria_foc_agents_extintors', (select id from public.topics where slug = 'bomb-t08-teoria-foc-agents-extintors'), 3, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-08-MAN.GRAL.008.pdf'), 'MAN.GRAL.008, § gasos inerts', 'Els sistemes es dissenyen per extingir el foc a nivells d''oxigen (normalment entre 10-12,5%) que permeten una exposició humana curta i segura per a l''evacuació, sense els efectes tòxics directes del CO₂.', null, '4e474659e63406d41f85c2155c03eb008e0ef5523ebf0a08ad002a8f66a084b3', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '4e474659e63406d41f85c2155c03eb008e0ef5523ebf0a08ad002a8f66a084b3')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Entre el 16 i el 18 %.', false), ('B', 'Entre el 10 i el 12,5 %.', true), ('C', 'Entre el 2 i el 5 %.', false), ('D', 'Per sota de l''1 %.', false)) as v(label, body, ok)
)
