with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el Manual operatiu bàsic de Física, què caracteritza una magnitud escalar?', 'Les magnituds escalars només tenen valor o mòdul (massa, temperatura, temps, volum); les vectorials, com la força, també tenen direcció i sentit.', 'bomb_t09_fisica', (select id from public.topics where slug = 'bomb-t09-fisica'), 1, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-09-MAN.GRAL.003.pdf'), 'MAN.GRAL.003, § magnituds escalars', 'Magnituds escalars Una magnitud escalar es defineix completament amb un número i la unitat corresponent.', null, '47622cc5d615ab5a7196ce1c9fb2ba49a8e4724ac326f59c354a1a8df1d6a12b', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '47622cc5d615ab5a7196ce1c9fb2ba49a8e4724ac326f59c354a1a8df1d6a12b')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Necessita un mòdul, una direcció i un sentit.', false), ('B', 'Es defineix completament amb un número i la unitat corresponent.', true), ('C', 'Es representa sempre amb una fletxa circular.', false), ('D', 'Només es pot expressar en unitats derivades.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
