  select 'Quina de les magnituds següents el manual de Física posa com a exemple de magnitud vectorial?', 'Una magnitud vectorial té valor, direcció i sentit; el manual utilitza la força com a exemple. Massa, temperatura i volum són escalars.', 'bomb_t09_fisica', (select id from public.topics where slug = 'bomb-t09-fisica'), 1, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-09-MAN.GRAL.003.pdf'), 'MAN.GRAL.003, § magnituds vectorials', 'La força és un exemple perfecte per il·lustrar aquest concepte.', null, 'd986856336bc520a7e59e8d159c24b84b2b4eb71841e66ab0dd6af765114b837', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'd986856336bc520a7e59e8d159c24b84b2b4eb71841e66ab0dd6af765114b837')
