insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('bombers-generalitat');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Quan un vehicle de bombers frena de cop i les eines mal subjectades continuen avançant, quina llei de Newton explica el fenomen segons el manual de Física?', 'Per la llei d''inèrcia, un cos en moviment continua amb moviment rectilini uniforme si cap força externa no l''atura; el manual en posa aquest exemple.', 'bomb_t09_fisica', (select id from public.topics where slug = 'bomb-t09-fisica'), 1, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-09-MAN.GRAL.003.pdf'), 'MAN.GRAL.003, § llei d''inèrcia', 'Quan un vehicle de bombers frena de cop, les eines mal subjectades a l''interior continuen el seu moviment cap endavant a causa de la inèrcia.', null, '9a213df1d5f3e178f472edf1ef062f0b4f29041a136b484aeec03ed353630341', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '9a213df1d5f3e178f472edf1ef062f0b4f29041a136b484aeec03ed353630341')
  returning id
), o as (
