  select 'Segons el manual de Física, quin efecte produeix un parell de forces sobre un objecte?', 'Un parell són dues forces iguals en mòdul i direcció i de sentit contrari, aplicades en punts diferents: fan girar el cos sense desplaçar-lo.', 'bomb_t09_fisica', (select id from public.topics where slug = 'bomb-t09-fisica'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-09-MAN.GRAL.003.pdf'), 'MAN.GRAL.003, § parell de forces', 'Aquestes dues forces tenen un efecte de rotació, però no de translació.', null, '9b57cbf02a86665e4fa000bf28253292ae2cff75e6031e675314db9862ce3323', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '9b57cbf02a86665e4fa000bf28253292ae2cff75e6031e675314db9862ce3323')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
