  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D''acord amb el manual de Física, en quina unitat es mesura el parell de forces o moment de força?', 'El parell es calcula multiplicant una de les forces per la distància entre els seus punts d''aplicació, i s''expressa en Nm. El kg·m/s és la unitat de la quantitat de moviment.', 'bomb_t09_fisica', (select id from public.topics where slug = 'bomb-t09-fisica'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-09-MAN.GRAL.003.pdf'), 'MAN.GRAL.003, § parell de forces', 'Es mesura en newton-metre (Nm), i es calcula multiplicant el valor d''una de les forces per la distància que separa els seus punts d''aplicació.', null, '50709d4f10e824bb13e4605eea9e8dec1b0fca93a16328f1c6ea26d34c5be5a6', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '50709d4f10e824bb13e4605eea9e8dec1b0fca93a16328f1c6ea26d34c5be5a6')
