  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual de Física, què passa amb un cotxe si la força neta o resultant que hi actua és nul·la?', 'Amb F = m·a, si la força resultant és zero l''acceleració també ho és: el cos es manté en repòs o a velocitat constant.', 'bomb_t09_fisica', (select id from public.topics where slug = 'bomb-t09-fisica'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-09-MAN.GRAL.003.pdf'), 'MAN.GRAL.003, § llei fonamental de la dinàmica', 'Si la força neta o resultant és nul·la, és a dir, la força amb què empenyem és igual a la resistència que s’oposa a avançar, el cotxe o no es mou o no accelera (manté la velocitat constant).', null, 'f3887112d134b522938940f55b70ab0fb8fe4f7b0ccbeb79b2685e0c043eac9a', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'f3887112d134b522938940f55b70ab0fb8fe4f7b0ccbeb79b2685e0c043eac9a')
