with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'En un cabestrant en què el cable s''enrotlla en diverses capes, quan és màxima la força de sortida al cable per a un mateix parell d''entrada, segons el manual de Física?', 'El torn funciona com una palanca giratòria: com més petit és el radi del tambor (braç de la resistència), més gran és la força al cable per al mateix parell.', 'bomb_t09_fisica', (select id from public.topics where slug = 'bomb-t09-fisica'), 3, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-09-MAN.GRAL.003.pdf'), 'MAN.GRAL.003, § torn', 'Així, quan el cable està gairebé estirat del tot, el radi del tambor és el més petit possible i, per la mateixa força (parell) d’entrada, la força de sortida (en el cable) és màxima.', null, '38274031937dcb1d4acea5459142461ad2956a8e2caf6b1a158be441841c1d36', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '38274031937dcb1d4acea5459142461ad2956a8e2caf6b1a158be441841c1d36')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Quan el cable està totalment enrotllat, perquè el radi del tambor és el més gran possible.', false), ('B', 'La força de sortida no depèn del radi del tambor.', false), ('C', 'Quan el cable està a mig enrotllar, perquè els radis es compensen.', false), ('D', 'Quan el cable està gairebé del tot estirat, perquè el radi del tambor és el més petit possible.', true)) as v(label, body, ok)
)
