with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual de Física, en quin principi es basa el funcionament del pla inclinat?', 'Com que el treball és força per distància, si es vol fer menys força cal recórrer més distància per assolir la mateixa alçada.', 'bomb_t09_fisica', (select id from public.topics where slug = 'bomb-t09-fisica'), 3, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-09-MAN.GRAL.003.pdf'), 'MAN.GRAL.003, § pla inclinat', 'El seu funcionament es basa en el principi de la conservació de l''energia.', null, '7f7d84ad2a184951cc555ae6484bc325e25d50ffc168053e40c59c355f9abea5', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '7f7d84ad2a184951cc555ae6484bc325e25d50ffc168053e40c59c355f9abea5')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'En el principi de Pascal: la pressió es transmet igual en totes direccions.', false), ('B', 'En el principi de la conservació de l''energia: es fa el mateix treball amb menys força al llarg de més distància.', true), ('C', 'En el principi d''Arquimedes: tot cos submergit rep una empenta vertical.', false), ('D', 'En la llei d''acció-reacció: la rampa empeny l''objecte cap amunt.', false)) as v(label, body, ok)
)
