  select 'Segons el manual d''electricitat, un ampere equival a:', 'La intensitat és la càrrega que passa per un punt del circuit per unitat de temps: 1 A = 1 C/s.', 'bomb_t11_electricitat', (select id from public.topics where slug = 'bomb-t11-electricitat'), 1, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-11-MAN.GRAL.005.pdf'), 'MAN.GRAL.005, § intensitat', 'Un ampere es defineix com el pas d''un Coulomb de càrrega per cada segon.', null, '252c6d9367254d9cd5e712be119cfaaecfae1a9ce8e19c464482635e64e7225e', false
