  select 'Segons el manual d''electricitat, el factor de potència és la relació entre:', 'El factor de potència (cos φ) mesura l''eficiència de l''ús de l''energia: potència activa (la que fa treball) dividida per la potència aparent (la total subministrada).', 'bomb_t11_electricitat', (select id from public.topics where slug = 'bomb-t11-electricitat'), 3, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-11-MAN.GRAL.005.pdf'), 'MAN.GRAL.005, § factor de potència', 'És la relació entre la potència activa (la que realment fa treball) i la potència aparent (la potència total que es subministra).', null, '48c9e0f4753eac7d5e884bc7e774ec74fb341d6b05df894661490e3f96e8788d', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '48c9e0f4753eac7d5e884bc7e774ec74fb341d6b05df894661490e3f96e8788d')
