with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual d''electricitat, quin és el llindar crític d''intensitat de corrent altern (a 50 Hz) per sota del qual la probabilitat de fibril·lació ventricular és menor en un percentatge elevat de la població?', 'Per sota de 30 mA hi pot haver dolor i contraccions, però la fibril·lació és menys probable. Amb corrent continu no es produeix fibril·lació ventricular.', 'bomb_t11_electricitat', (select id from public.topics where slug = 'bomb-t11-electricitat'), 3, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-11-MAN.GRAL.005.pdf'), 'MAN.GRAL.005, § fibril·lació ventricular', 'S''ha establert el llindar crític de 30 mA (a 50 Hz): per sota d''aquest valor, tot i que es pot experimentar dolor, contraccions musculars o dificultat per respirar, la probabilitat de fibril·lació ventricular és menor en un percentatge elevat de la població.', null, 'c6b22dba51bc7e955f99a822db6f020f73d1927d4c5e5ce43d6fbbc122383146', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'c6b22dba51bc7e955f99a822db6f020f73d1927d4c5e5ce43d6fbbc122383146')
  returning id
