with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual d''electricitat, quina afirmació és CORRECTA sobre els efectes del corrent continu (DC) en el cor?', 'El manual diu que amb DC no hi ha fibril·lació ventricular, però sí que hi pot haver una contracció involuntària del cor i aturada cardíaca amb intensitats superiors.', 'bomb_t11_electricitat', (select id from public.topics where slug = 'bomb-t11-electricitat'), 3, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-11-MAN.GRAL.005.pdf'), 'MAN.GRAL.005, § corrent continu i cos humà', 'Amb corrent continu (DC), no es produeix fibril·lació ventricular. […] No obstant això, amb intensitats superiors, sí que pot haver-hi una contracció involuntària del cor que resulti en una aturada cardíaca.', null, '2926a8b311e8dffb5451cb6bd929ea86a3f6d53cbb039998a432a103724f56a1', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '2926a8b311e8dffb5451cb6bd929ea86a3f6d53cbb039998a432a103724f56a1')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Produeix fibril·lació ventricular a partir de 3 mA.', false), ('B', 'No té cap efecte sobre el cor, sigui quina sigui la intensitat.', false), ('C', 'No produeix fibril·lació ventricular, però a intensitats altes pot provocar una contracció involuntària que acabi en aturada cardíaca.', true), ('D', 'És més perillós que l''altern perquè produeix fibril·lació a qualsevol intensitat.', false)) as v(label, body, ok)
)
