with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Prop d''un cable d''alta tensió caigut a terra, què recomana el manual d''electricitat per reduir el risc de la tensió de pas?', 'Com més separats estan els peus i més a prop del cable, més diferència de potencial i més corrent pel cos; per això cal fer passos petits amb els peus junts.', 'bomb_t11_electricitat', (select id from public.topics where slug = 'bomb-t11-electricitat'), 3, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-11-MAN.GRAL.005.pdf'), 'MAN.GRAL.005, § tensió de pas', 'En aquests casos es recomana fer passos petits amb els peus ben junts i tocant-se, i mai estirar-se a terra ni caure.', null, '48289fedd3c3c393273ccf2e157cb9a7eb639f10b015b082556906095a114b00', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '48289fedd3c3c393273ccf2e157cb9a7eb639f10b015b082556906095a114b00')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Fer passes llargues per allunyar-se com més aviat millor.', false), ('B', 'Fer passos petits amb els peus ben junts i tocant-se, sense estirar-se a terra ni caure.', true), ('C', 'Estirar-se a terra per repartir el contacte.', false), ('D', 'Córrer saltant amb els dos peus alhora.', false)) as v(label, body, ok)
)
