  select 'Segons el manual d''electricitat, quina característica d''un conductor li permet transportar més corrent?', 'Com més curt i gruixut és el conductor, menys resistència ofereix i més corrent pot transportar.', 'bomb_t11_electricitat', (select id from public.topics where slug = 'bomb-t11-electricitat'), 3, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-11-MAN.GRAL.005.pdf'), 'MAN.GRAL.005, § conductors', 'Com més curt i gruixut és el conductor, més corrent pot transportar.', null, 'a339e91ba3b8cb88892a287e593a144b2016c864b00dc0975c919cd4387e73c7', false
