  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual d''instal·lacions, quin és el component majoritari del gas natural?', 'El gas natural és majoritàriament metà (90-95 %), amb petites quantitats de nitrogen, CO₂ i altres gasos.', 'bomb_t12_installacions', (select id from public.topics where slug = 'bomb-t12-installacions'), 1, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.GRAL.007-Tema-12.-Installacions.pdf'), 'MAN.GRAL.007, § gas natural', 'La seva composició varia segons l’origen, però està format majoritàriament per metà (90–95%), tot i que també pot contenir petites quantitats de nitrogen, CO₂ i altres gasos.', null, '3757751c03e6f64f13876f25a71cdca8ac4e0f72e73f4606a59238fc329abca2', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '3757751c03e6f64f13876f25a71cdca8ac4e0f72e73f4606a59238fc329abca2')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El metà, entre el 90 i el 95 %.', true), ('B', 'El butà, entre el 60 i el 70 %.', false), ('C', 'El propà, aproximadament el 50 %.', false), ('D', 'El nitrogen, aproximadament el 78 %.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('bombers-generalitat');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual d''instal·lacions, quins són els elements principals d''una instal·lació domèstica de gas butà envasat?', 'En els habitatges no connectats a la xarxa canalitzada, la instal·lació de butà consta de bombona, regulador de pressió i tub flexible.', 'bomb_t12_installacions', (select id from public.topics where slug = 'bomb-t12-installacions'), 1, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.GRAL.007-Tema-12.-Installacions.pdf'), 'MAN.GRAL.007, § instal·lació de gas butà', 'El subministrament més habitual dels habitatges que no estan connectats a la xarxa de gas canalitzat, és el gas butà envasat en bombones, i els elements principals de la instal·lació de gas butà són la bombona, el regulador de pressió i el tub flexible.', null, '231c3d8a80d3d8183b362d9c217c4075192254ba78c161ba5e2339d438e9cfad', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '231c3d8a80d3d8183b362d9c217c4075192254ba78c161ba5e2339d438e9cfad')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La bombona, el regulador de pressió i el tub flexible.', true), ('B', 'La clau d''escomesa, el comptador i el muntant.', false), ('C', 'El dipòsit fix, el vaporitzador i la clau d''edifici.', false), ('D', 'La bombona, el comptador i la clau de muntant col·lectiu.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
