)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('bombers-generalitat');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual d''instal·lacions, què és l''IGA?', 'L''interruptor general automàtic és un magnetotèrmic de capçalera. Abans es deia ICP i limitava la potència contractada, funció que ara fa el comptador intel·ligent.', 'bomb_t12_installacions', (select id from public.topics where slug = 'bomb-t12-installacions'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.GRAL.007-Tema-12.-Installacions.pdf'), 'MAN.GRAL.007, § IGA', 'L’IGA (Interruptor General Automàtic) és un magnetotèrmic que es col·loca al principi del quadre elèctric i protegeix tota la instal·lació domèstica.', null, 'd63f4d3f68109cf58db04a5ded73083dc0f74ebf6a39a2a284c2b407c19fa550', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'd63f4d3f68109cf58db04a5ded73083dc0f74ebf6a39a2a284c2b407c19fa550')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Un magnetotèrmic que es col·loca al principi del quadre elèctric i protegeix tota la instal·lació domèstica.', true), ('B', 'Un diferencial de 300 mA per a enllumenat públic.', false), ('C', 'La unitat que permet deixar fora de servei una centralització de comptadors.', false), ('D', 'El dispositiu que limita la potència contractada en els comptadors actuals.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('bombers-generalitat');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual d''instal·lacions, de quin conjunt d''elements depèn la protecció de les persones davant contactes elèctrics?', 'Perquè el diferencial actuï, el corrent de fuita ha de tenir camí de retorn; per això el neutre dels transformadors va a terra i les masses tenen presa de terra.', 'bomb_t12_installacions', (select id from public.topics where slug = 'bomb-t12-installacions'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.GRAL.007-Tema-12.-Installacions.pdf'), 'MAN.GRAL.007, § diferencials', 'La protecció de les persones depèn del conjunt: neutre connectat a terra + diferencial + presa de terra de les masses.', null, '32e86b5d81630a17adfaa718f2174cf7dfff04ff99b2fd28a5425a2fbfe3676e', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '32e86b5d81630a17adfaa718f2174cf7dfff04ff99b2fd28a5425a2fbfe3676e')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Només del magnetotèrmic de cada circuit.', false), ('B', 'De l''IGA i del comptador intel·ligent.', false), ('C', 'Del neutre connectat a terra, del diferencial i de la presa de terra de les masses.', true), ('D', 'De la CGP i de l''interruptor general de maniobra.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('bombers-generalitat');
