)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('bombers-generalitat');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual d''instal·lacions, en què consisteix la segona regla d''or («prevenir qualsevol possible realimentació»)?', 'Cal bloquejar els dispositius de tall, tenir en compte les realimentacions automàtiques i senyalitzar («Treballs en curs», «No connectar»).', 'bomb_t12_installacions', (select id from public.topics where slug = 'bomb-t12-installacions'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.GRAL.007-Tema-12.-Installacions.pdf'), 'MAN.GRAL.007, § 5 regles d''or', '2) Prevenir qualsevol possible realimentació Els dispositius utilitzats per desconnectar la instal·lació s’han d’assegurar contra qualsevol possible reconnexió, amb cadenats o bloquejos.', null, '0611a45571fffa4aa34399a54d7235d18ababa476bf1f159bede617cbec18bb7', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '0611a45571fffa4aa34399a54d7235d18ababa476bf1f159bede617cbec18bb7')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'En assegurar els dispositius de desconnexió contra qualsevol reconnexió amb cadenats o bloquejos i senyalitzar els treballs.', true), ('B', 'En comprovar amb un voltímetre que no hi ha tensió.', false), ('C', 'En connectar els conductors a terra i en curtcircuit.', false), ('D', 'En delimitar la zona de treball amb cinta.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('bombers-generalitat');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual d''instal·lacions, quina afirmació sobre el gas natural és CORRECTA?', 'El gas natural és lleuger i inodor; l''odoritzant permet detectar les fuites. Els GLP (butà i propà) es distribueixen liquats.', 'bomb_t12_installacions', (select id from public.topics where slug = 'bomb-t12-installacions'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.GRAL.007-Tema-12.-Installacions.pdf'), 'MAN.GRAL.007, § gas natural', 'El gas natural és menys dens que l’aire i té un alt poder calorífic, cosa que el fa molt eficient com a combustible. […] No és tòxic i és inolor (per això se li afegeix un component químic odoritzant per facilitar-ne la detecció en cas de fuita).', null, '0272226d6d3d08b7d9c19a224057c40e57b1d5ecd30a409b5a461067521cc1f3', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '0272226d6d3d08b7d9c19a224057c40e57b1d5ecd30a409b5a461067521cc1f3')
  returning id
), o as (
