  select 'Segons el manual d''hidràulica, què és la pressió relativa o manomètrica?', 'La pressió absoluta es mesura des del buit absolut (pressió 0); la relativa és la diferència entre la pressió real i l''atmosfèrica.', 'bomb_t13_hidraulica_bombes', (select id from public.topics where slug = 'bomb-t13-hidraulica-bombes'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-13-MAN.GRAL.009.pdf'), 'MAN.GRAL.009, § pressió absoluta i relativa', 'Pressió relativa (o manomètrica): és la diferència entre la pressió real i la pressió atmosfèrica en aquell lloc, o dit d’una altra manera, és la pressió mesurada a partir de la pressió atmosfèrica.', null, 'f763bb8a076e2759ec2840021641c6503d2446275c2b2f9e5f7f3ca2da789a2e', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'f763bb8a076e2759ec2840021641c6503d2446275c2b2f9e5f7f3ca2da789a2e')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La pressió total mesurada des del buit absolut.', false), ('B', 'La pressió de vapor de l''aigua a temperatura ambient.', false), ('C', 'La pressió dinàmica deguda a la velocitat del fluid.', false), ('D', 'La pressió mesurada a partir de la pressió atmosfèrica del lloc.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('bombers-generalitat');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual d''hidràulica, a quina temperatura aproximada bull l''aigua a dalt d''una muntanya de 3.000 m?', 'A més alçada, la pressió atmosfèrica és menor i l''aigua bull a menys temperatura (uns 90 °C a 3.000 m).', 'bomb_t13_hidraulica_bombes', (select id from public.topics where slug = 'bomb-t13-hidraulica-bombes'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-13-MAN.GRAL.009.pdf'), 'MAN.GRAL.009, § pressió de vapor', 'Per exemple, a nivell del mar (1 bar de pressió) l’aigua bull a 100 ºC, però a dalt d’una muntanya de 3000 m, la pressió atmosfèrica és menor i l’aigua bull a menys temperatura (uns 90 ºC)', null, '5bfe3d8b8ed9b341f06c0c7f8a1d5e65fd2662848556f25cf88b74b2536e444c', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '5bfe3d8b8ed9b341f06c0c7f8a1d5e65fd2662848556f25cf88b74b2536e444c')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'A 100 °C, com a nivell del mar.', false), ('B', 'A uns 90 °C.', true), ('C', 'A uns 110 °C.', false), ('D', 'A uns 70 °C.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('bombers-generalitat');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual d''hidràulica, per què s''afegeixen humectants o tensioactius a l''aigua d''extinció?', 'Els tensioactius (sabons) redueixen la tensió superficial: l''aigua penetra millor en materials porosos i es poden formar bombolles d''escuma.', 'bomb_t13_hidraulica_bombes', (select id from public.topics where slug = 'bomb-t13-hidraulica-bombes'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-13-MAN.GRAL.009.pdf'), 'MAN.GRAL.009, § tensió superficial', 'Amb additius humectants i tensioactius (sabons) podem reduir la tensió superficial de l’aigua amb l’objectiu de fer que penetri més fàcilment en materials sòlids porosos, o per la formació de bombolles (escumes d’extinció).', null, '87a0371618357dd72431eae413e3f5961a0838f25949afe19d54421523e11496', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '87a0371618357dd72431eae413e3f5961a0838f25949afe19d54421523e11496')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Per augmentar la viscositat i que l''aigua s''adhereixi millor.', false), ('B', 'Per augmentar la densitat i que el raig arribi més lluny.', false), ('C', 'Per reduir la tensió superficial i que l''aigua penetri més fàcilment en sòlids porosos o formi escumes.', true), ('D', 'Per reduir la pressió de vapor i evitar la cavitació.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('bombers-generalitat');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual d''hidràulica, què estableix l''equació de continuïtat per a un fluid incompressible com l''aigua?', 'Es basa en la conservació de la massa: el que entra per un extrem d''una conducció sense derivacions surt per l''altre; si la secció es redueix, augmenta la velocitat.', 'bomb_t13_hidraulica_bombes', (select id from public.topics where slug = 'bomb-t13-hidraulica-bombes'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-13-MAN.GRAL.009.pdf'), 'MAN.GRAL.009, § equació de continuïtat', 'En un fluid incompressible, com l''aigua, l''equació de continuïtat estableix que el cabal és constant en qualsevol punt d''una conducció.', null, 'a34d4a70123abe443d970fd9745180d974afa960b02b457d15ade9fcc91556d4', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'a34d4a70123abe443d970fd9745180d974afa960b02b457d15ade9fcc91556d4')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Que el cabal és constant en qualsevol punt d''una conducció.', true), ('B', 'Que la pressió és constant en qualsevol punt d''una conducció.', false), ('C', 'Que la velocitat és la mateixa en totes les seccions.', false), ('D', 'Que l''energia total es perd per fregament.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('bombers-generalitat');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual d''hidràulica, què passa amb un fluid que circula per un conducte tancat que s''estreny (efecte Venturi)?', 'Per mantenir el cabal, el fluid accelera a l''estretament; segons Bernoulli, el que guanya en pressió dinàmica ho perd en pressió estàtica, i fins i tot pot crear succió.', 'bomb_t13_hidraulica_bombes', (select id from public.topics where slug = 'bomb-t13-hidraulica-bombes'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-13-MAN.GRAL.009.pdf'), 'MAN.GRAL.009, § efecte Venturi', 'Efecte Venturi L''efecte Venturi és un fenomen físic que es produeix quan un fluid circula per un conducte tancat que s’estreny, disminueix la seva pressió ja que augmenta la velocitat.', null, '0e01c116740e88124738a36c6a340414a73672cac2b5c705a4a5d8837cf6ee27', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '0e01c116740e88124738a36c6a340414a73672cac2b5c705a4a5d8837cf6ee27')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Disminueix la velocitat i augmenta la pressió.', false), ('B', 'Augmenten alhora la velocitat i la pressió.', false), ('C', 'Disminueix el cabal en la mateixa proporció que la secció.', false), ('D', 'Augmenta la velocitat i disminueix la pressió.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('bombers-generalitat');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual d''hidràulica, què provoca el cop d''ariet en una instal·lació?', 'En tancar de cop, l''energia cinètica del fluid es transforma en energia de pressió i es crea una ona de sobrepressió que pot superar diverses vegades la pressió de treball.', 'bomb_t13_hidraulica_bombes', (select id from public.topics where slug = 'bomb-t13-hidraulica-bombes'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-13-MAN.GRAL.009.pdf'), 'MAN.GRAL.009, § cop d''ariet', 'Cop d’Ariet El cop d’ariet és un fenomen físic de sobrepressió que es produeix en les instal·lacions hidràuliques a causa de les reduccions brusques de cabal.', null, '842065d11ef47a5f9c9e55f3bc37df5ed20a6d0beb4d5c8b2b2f07ee8ea1b953', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '842065d11ef47a5f9c9e55f3bc37df5ed20a6d0beb4d5c8b2b2f07ee8ea1b953')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Una baixada de pressió que forma bombolles de vapor a l''aspiració.', false), ('B', 'Una reducció brusca de cabal, per exemple en tancar de sobte una vàlvula.', true), ('C', 'L''estretament de la secció d''un conducte.', false), ('D', 'L''augment de la viscositat de l''aigua amb el fred.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('bombers-generalitat');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual d''hidràulica, quan es produeix la cavitació?', 'Les bombolles de vapor col·lapsen en arribar a zones de més pressió, arrenquen material, provoquen vibracions i redueixen el rendiment.', 'bomb_t13_hidraulica_bombes', (select id from public.topics where slug = 'bomb-t13-hidraulica-bombes'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-13-MAN.GRAL.009.pdf'), 'MAN.GRAL.009, § cavitació', 'Cavitació La cavitació és un fenomen físic no desitjat que es produeix quan, en una zona del circuit la pressió del líquid baixa tant que es formen bombolles de vapor d’aigua.', null, 'b2208c28ac5b66dbdaa1a64ba14ffa386df3016f6fa3d58f168ad5883c09664f', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'b2208c28ac5b66dbdaa1a64ba14ffa386df3016f6fa3d58f168ad5883c09664f')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Quan en una zona del circuit la pressió del líquid baixa tant que es formen bombolles de vapor.', true), ('B', 'Quan es tanca bruscament una vàlvula i es crea una sobrepressió.', false), ('C', 'Quan la mànega fa un colze massa tancat.', false), ('D', 'Quan la bomba treballa a cabal zero amb la vàlvula de sobrepressió oberta.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('bombers-generalitat');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual d''hidràulica, en quin tipus d''operacions es dona especialment la cavitació?', 'La cavitació apareix sobretot en aspiració, perquè el líquid arriba a la bomba empès pel buit i hi ha pressions molt baixes.', 'bomb_t13_hidraulica_bombes', (select id from public.topics where slug = 'bomb-t13-hidraulica-bombes'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-13-MAN.GRAL.009.pdf'), 'MAN.GRAL.009, § cavitació', 'Aquest fenomen es dona especialment en operacions d’aspiració, quan el líquid és empès cap a la bomba pel buit generat.', null, '7049bf4b05d4c1abecbdd0424b7f0cf511cc40795252d6ac72aa4ca2d013b638', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '7049bf4b05d4c1abecbdd0424b7f0cf511cc40795252d6ac72aa4ca2d013b638')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'En les esteses de mànegues en paral·lel.', false), ('B', 'En l''alimentació des d''un hidrant amb pressió.', false), ('C', 'En operacions d''aspiració.', true), ('D', 'En el tancament lent de les llances.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('bombers-generalitat');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual d''hidràulica, què passa quan es fa una estesa doble de mànegues en paral·lel entre l''hidrant i l''aspiració de la bomba?', 'Repartir el cabal entre dues mànegues redueix molt la velocitat en cadascuna i, per tant, les pèrdues de càrrega.', 'bomb_t13_hidraulica_bombes', (select id from public.topics where slug = 'bomb-t13-hidraulica-bombes'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-13-MAN.GRAL.009.pdf'), 'MAN.GRAL.009, § mànegues en paral·lel', 'En canvi, quan connectem mànegues en paral·lel, és a dir, fem una estesa de mànegues doble entre dos punts, per exemple de l’hidrant a l’aspiració de la bomba, les pèrdues de càrrega del conjunt baixen dràsticament i el cabal gairebé es duplica.', null, '3cd1532ae43c21cbc51dadbe1513a55b7ff50d2dd82ae72b63eb4bc7fc016a05', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '3cd1532ae43c21cbc51dadbe1513a55b7ff50d2dd82ae72b63eb4bc7fc016a05')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Les pèrdues de càrrega es dupliquen i el cabal es redueix a la meitat.', false), ('B', 'Les pèrdues de càrrega del conjunt baixen dràsticament i el cabal gairebé es duplica.', true), ('C', 'La pressió a la bomba es duplica però el cabal no varia.', false), ('D', 'No hi ha cap efecte, perquè el cabal depèn només de l''hidrant.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('bombers-generalitat');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual d''hidràulica, en quin punt d''una bomba centrífuga és més probable que es produeixi cavitació?', 'Són els punts amb les pressions més baixes del circuit, on es formen més fàcilment les bombolles de vapor.', 'bomb_t13_hidraulica_bombes', (select id from public.topics where slug = 'bomb-t13-hidraulica-bombes'), 3, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-13-MAN.GRAL.009.pdf'), 'MAN.GRAL.009, § cavitació', 'El lloc on és més probable que es produeixi la cavitació és a la l''entrada axial de la bomba i en el dors dels àleps del rodet, que és on s''assoleixen les pressions més baixes del circuit, facilitant la formació de bombolles de vapor.', null, '369bc20171f33b68edd140b6acf1610d93a1cc466cffb78b081d9a30e54cb265', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '369bc20171f33b68edd140b6acf1610d93a1cc466cffb78b081d9a30e54cb265')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Al col·lector de sortida tangencial.', false), ('B', 'A la vàlvula de sobrepressió.', false), ('C', 'A la llança, en el moment d''obrir-la.', false), ('D', 'A l''entrada axial de la bomba i al dors dels àleps del rodet.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('bombers-generalitat');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual d''hidràulica, com és la corba pressió/cabal d''una bomba volumètrica?', 'Pel seu disseny de desplaçament positiu, la volumètrica dona un cabal gairebé constant; la pressió puja fins al límit de la vàlvula de sobrepressió o del trencament d''algun component.', 'bomb_t13_hidraulica_bombes', (select id from public.topics where slug = 'bomb-t13-hidraulica-bombes'), 3, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-13-MAN.GRAL.009.pdf'), 'MAN.GRAL.009, § bombes volumètriques', 'El seu disseny de desplaçament positiu fa que el cabal sigui gairebé constant independentment de la pressió. […] Per això, la corba pressió/cabal és gairebé una línia recta vertical.', null, 'e7f110ad13de57c886905fc100910daf6aefc23d928ef48620b934c7116bedc3', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'e7f110ad13de57c886905fc100910daf6aefc23d928ef48620b934c7116bedc3')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Una corba descendent: a més cabal, menys pressió.', false), ('B', 'Gairebé una línia recta vertical, perquè el cabal és gairebé constant independentment de la pressió.', true), ('C', 'Una línia horitzontal, perquè la pressió és constant.', false), ('D', 'Idèntica a la d''una bomba centrífuga.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('bombers-generalitat');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Quina afirmació és CORRECTA sobre la constitució d''una bomba centrífuga segons el manual d''hidràulica?', 'El líquid entra pel centre del rodet i la força centrífuga l''impulsa cap a l''exterior; no hi ha estanqueïtat entre rodet i carcassa.', 'bomb_t13_hidraulica_bombes', (select id from public.topics where slug = 'bomb-t13-hidraulica-bombes'), 3, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-13-MAN.GRAL.009.pdf'), 'MAN.GRAL.009, § bombes centrífugues', 'Consten d''una entrada axial, un rodet i un col·lector amb sortida tangencial. […] Entre el rodet i la carcassa exterior no hi ha estanqueïtat.', null, 'ac6731393c2fb66dc2dcd3aec1e6b63ce64ab52eb13da02342cb715cae31d181', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'ac6731393c2fb66dc2dcd3aec1e6b63ce64ab52eb13da02342cb715cae31d181')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Consta d''una entrada axial, un rodet i un col·lector amb sortida tangencial, i entre el rodet i la carcassa no hi ha estanqueïtat.', true), ('B', 'Consta de pistons i vàlvules, amb estanqueïtat total entre les cambres.', false), ('C', 'El líquid entra per la perifèria del rodet i surt pel centre.', false), ('D', 'Té dos engranatges que giren en sentit contrari i comprimeixen el líquid.', false)) as v(label, body, ok)
)
