with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual d''hidràulica, de què depèn la força de reacció del raig per a una mateixa llança?', 'La velocitat de l''aigua a la sortida genera una força en sentit contrari; a més pressió, més velocitat i més reacció que ha de suportar el bomber.', 'bomb_t13_hidraulica_bombes', (select id from public.topics where slug = 'bomb-t13-hidraulica-bombes'), 3, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-13-MAN.GRAL.009.pdf'), 'MAN.GRAL.009, § reacció del raig', 'Per una mateixa llança, la força de reacció depèn de la pressió, del cabal i de la forma del raig.', null, 'a172319286bcaaf5bc205e8f75f16a38139de40c0d322f1ef77f4a01d6351319', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'a172319286bcaaf5bc205e8f75f16a38139de40c0d322f1ef77f4a01d6351319')
  returning id
), o as (
