with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el Manual operatiu bàsic de cartografia i orientació, la latitud és:', 'Els paral·lels serveixen per mesurar la latitud, angle respecte a l''equador; la longitud es mesura respecte a un meridià i l''azimut és l''angle respecte al nord.', 'bomb_t14_cartografia_orientacio', (select id from public.topics where slug = 'bomb-t14-cartografia-orientacio'), 1, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-14-MAN.GRAL.002.pdf'), 'MAN.GRAL.002, § paral·lels i latitud', 'S''utilitzen per a mesurar la latitud, que és l''angle d''un punt respecte a l''equador.', null, '0e0a097e95a8b01ff1926f8cfe26ce8216d4c3480e524afbce644107288eb420', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '0e0a097e95a8b01ff1926f8cfe26ce8216d4c3480e524afbce644107288eb420')
  returning id
), o as (
