  select 'Segons el manual de cartografia, la brúixola ens indica:', 'La brúixola assenyala el Nord magnètic, que no coincideix exactament amb el Nord geogràfic.', 'bomb_t14_cartografia_orientacio', (select id from public.topics where slug = 'bomb-t14-cartografia-orientacio'), 1, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-14-MAN.GRAL.002.pdf'), 'MAN.GRAL.002, § brúixola', 'La brúixola La brúixola és un instrument que ens indica el Nord magnètic.', null, 'b10e87a876c17371c8011bc410b7c783deefc8f6272c54f1509e6c41ebc7129d', false
