  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual de cartografia, què és el datum?', 'El datum és el sistema de referència; una mateixa coordenada pot situar punts diferents segons el datum.', 'bomb_t14_cartografia_orientacio', (select id from public.topics where slug = 'bomb-t14-cartografia-orientacio'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-14-MAN.GRAL.002.pdf'), 'MAN.GRAL.002, § datum', 'El Datum El datum és el sistema de referència que defineix la posició i orientació d’un sistema de coordenades.', null, 'ced38c667184bb3b780db09af12fad69413fe01e578dd8387417393bfa7b7630', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'ced38c667184bb3b780db09af12fad69413fe01e578dd8387417393bfa7b7630')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La separació vertical entre dues corbes de nivell.', false), ('B', 'El sistema de referència que defineix la posició i orientació d''un sistema de coordenades.', true), ('C', 'La diferència angular entre el Nord magnètic i el geogràfic.', false), ('D', 'La relació entre una distància al mapa i la mateixa distància al terreny.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
