with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual de cartografia, quin d''aquests mapes està a escala més gran?', 'Com més petit és el denominador, més gran és l''escala: un 1:10.000 té escala més gran que un 1:50.000.', 'bomb_t14_cartografia_orientacio', (select id from public.topics where slug = 'bomb-t14-cartografia-orientacio'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-14-MAN.GRAL.002.pdf'), 'MAN.GRAL.002, § escala gran i petita', 'Per exemple, un mapa a escala 1:10.000 està a escala més gran que un 1:50.000.', null, '037606c709dc195762c1bcf1cc4c1bdf52e749e3fd7ec8566e7f6005851655c9', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '037606c709dc195762c1bcf1cc4c1bdf52e749e3fd7ec8566e7f6005851655c9')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Un mapa a escala 1:50.000.', false), ('B', 'Un mapa a escala 1:25.000.', false), ('C', 'Un mapa a escala 1:10.000.', true), ('D', 'Un mapa a escala 1:100.000.', false)) as v(label, body, ok)
)
