with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual de cartografia, com s''anomena la corba de nivell dibuixada amb un traç més gruixut, generalment cada 5 corbes?', 'La corba mestra es dibuixa més gruixuda per facilitar la lectura i el recompte de corbes.', 'bomb_t14_cartografia_orientacio', (select id from public.topics where slug = 'bomb-t14-cartografia-orientacio'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-14-MAN.GRAL.002.pdf'), 'MAN.GRAL.002, § corba mestra', 'Cada cert numero de corbes (generalment cada 5 corbes) es dibuixa la corba amb un traç més gruixut, és l’anomenada corba mestra, per facilitar la lectura del mapa i el recompte de corbes.', null, 'a7932bd918d40f4bd637ee18ff1468ed7f384c83edf8b35f22417f2b2c0e42f3', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'a7932bd918d40f4bd637ee18ff1468ed7f384c83edf8b35f22417f2b2c0e42f3')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Corba auxiliar.', false), ('B', 'Corba d''equidistància.', false), ('C', 'Corba mestra.', true), ('D', 'Isòbata.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('bombers-generalitat');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual de cartografia, què és l''equidistància d''un mapa topogràfic?', 'L''equidistància és la separació vertical entre talls; ha de constar al mapa i depèn de l''escala.', 'bomb_t14_cartografia_orientacio', (select id from public.topics where slug = 'bomb-t14-cartografia-orientacio'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-14-MAN.GRAL.002.pdf'), 'MAN.GRAL.002, § equidistància', 'La separació vertical entre els talls de les llesques s''anomena equidistància, i ha de venir indicada en el mapa ja que és una informació molt valuosa per interpretar el relleu mitjançant les corbes de nivell i per comptar la diferència d’altitud entre dos punts del mapa.', null, 'be18d121d34489e191ddfde1e5a024c659711e8d4b3c0214798f6b055a1fc42d', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'be18d121d34489e191ddfde1e5a024c659711e8d4b3c0214798f6b055a1fc42d')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La distància horitzontal entre dues corbes mestres.', false), ('B', 'La diferència entre el Nord geogràfic i el magnètic.', false), ('C', 'La distància entre dues línies de la quadrícula UTM.', false), ('D', 'La separació vertical entre dues corbes de nivell consecutives.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
