with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual de cartografia, quin és el gran avantatge de l''escala gràfica respecte a la numèrica?', 'En una fotocòpia o en un mapa digital ampliat, l''escala gràfica canvia de mida amb el mapa; la numèrica deixaria de ser vàlida.', 'bomb_t14_cartografia_orientacio', (select id from public.topics where slug = 'bomb-t14-cartografia-orientacio'), 3, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-14-MAN.GRAL.002.pdf'), 'MAN.GRAL.002, § escala gràfica', 'El gran avantatge de l''escala gràfica és que si el mapa s''amplia o es redueix (per exemple, en una fotocòpia, un mapa digital), l''escala gràfica es redimensiona amb ell, mantenint la seva relació amb la realitat.', null, '191fc6209872738db481a8906f0b5837de914efdf50afb5122116f7d45d5b992', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '191fc6209872738db481a8906f0b5837de914efdf50afb5122116f7d45d5b992')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Que permet calcular l''altitud de qualsevol punt sense corbes de nivell.', false), ('B', 'Que es redimensiona amb el mapa si aquest s''amplia o es redueix, i manté la relació amb la realitat.', true), ('C', 'Que corregeix automàticament la declinació magnètica.', false), ('D', 'Que és més precisa que l''escala numèrica en qualsevol circumstància.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('bombers-generalitat');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual de cartografia, sobre la diferència entre el Nord magnètic i el Nord geogràfic, és correcte afirmar que:', 'El Nord magnètic no coincideix amb el geogràfic; la desviació varia segons lloc i any i el mapa l''ha d''indicar.', 'bomb_t14_cartografia_orientacio', (select id from public.topics where slug = 'bomb-t14-cartografia-orientacio'), 3, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-14-MAN.GRAL.002.pdf'), 'MAN.GRAL.002, § declinació magnètica', 'Tinguem en compte que el Nord magnètic no coincideix exactament amb el Nord geogràfic, hi ha una petita desviació que varia amb el lloc i amb els anys, per això ha de venir indicada en el mapa.', null, 'af66a11aa1fda2dbaad27c105729c1bddaf0d7e1183e46f916f823ef9b689708', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'af66a11aa1fda2dbaad27c105729c1bddaf0d7e1183e46f916f823ef9b689708')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'És constant a tot el planeta i no cal indicar-la.', false), ('B', 'Només existeix a l''hemisferi sud.', false), ('C', 'Depèn de l''escala del mapa.', false), ('D', 'Varia amb el lloc i amb els anys i, per això, ha de venir indicada en el mapa.', true)) as v(label, body, ok)
)
