with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual de cartografia, per obtenir una lectura fiable amb la brúixola cal:', 'Si s''inclina, l''agulla queda travada; els vehicles, torres elèctriques o aparells electrònics alteren la lectura.', 'bomb_t14_cartografia_orientacio', (select id from public.topics where slug = 'bomb-t14-cartografia-orientacio'), 3, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-14-MAN.GRAL.002.pdf'), 'MAN.GRAL.002, § ús de la brúixola', 'És important mantenir la horitzontalitat de la brúixola. […] També és molt important allunyar la brúixola d’altres camps magnètics i objectes metàl·lics que poden alterar la lectura (torres elèctriques, cotxes, dispositius electrònics, corrents elèctrics potents, edificis amb estructures d’acer i formigó armat...)', null, '18d10dc58fb2d944147a700e520eb619a5e6fae779b4fc2bddb0c274064bd9d5', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '18d10dc58fb2d944147a700e520eb619a5e6fae779b4fc2bddb0c274064bd9d5')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Mantenir-la horitzontal i allunyada d''objectes metàl·lics i camps magnètics.', true), ('B', 'Inclinar-la cap a l''objectiu per afinar la visual.', false), ('C', 'Recolzar-la sobre el capó del vehicle per estabilitzar-la.', false), ('D', 'Situar-la a prop d''un dispositiu electrònic amb GPS per corregir-la.', false)) as v(label, body, ok)
)
