  select 'Segons el manual de construcció, quina de les afirmacions següents sobre els elements no estructurals és correcta?', 'Els envans i falsos sostres organitzen l''espai però no aporten estabilitat.', 'bomb_t15_construccio', (select id from public.topics where slug = 'bomb-t15-construccio'), 3, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.GRAL.006-Tema-15.-Manual-Op.-basic-construccio.pdf'), 'MAN.GRAL.006, § elements no estructurals', 'Elements no estructurals Els elements no estructurals són totes aquelles parts d’un edifici que no tenen funció resistent directa, és a dir, no sostenen càrregues ni contribueixen de manera principal a l’estabilitat global de l’estructura.', null, 'b7ddf81e7ab91c32b559492d1f4d448d2c01108b21d8406d310c275424a8568c', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'b7ddf81e7ab91c32b559492d1f4d448d2c01108b21d8406d310c275424a8568c')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
