  select 'Segons el manual d''assistències tècniques, què indica un lladruc agut i repetitiu d''un gos?', 'El lladruc agut i repetitiu reflecteix inseguretat; el greu i mantingut, seguretat i voluntat de defensa.', 'bomb_t16_assistencies_tecniques', (select id from public.topics where slug = 'bomb-t16-assistencies-tecniques'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-16-MAN.ATXX.000.pdf'), 'MAN.ATXX.000, § lladruc', 'Un lladruc agut i repetitiu reflecteix inseguretat i nerviosisme; en aquests casos convé no acorralar l’animal i deixar-li sempre una via d’escapament.', null, 'b1100d8687e6a0cb59d635b6b6146598c1294fe9f190f389cb04aad572d001c5', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'b1100d8687e6a0cb59d635b6b6146598c1294fe9f190f389cb04aad572d001c5')
  returning id
), o as (
