)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('bombers-generalitat');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el criteri operatiu dels Bombers de la Generalitat que recull el manual, quan s''ha d''intervenir en emergències amb himenòpters?', 'Cal intervenir només si hi ha risc immediat i afectació directa a tercers, i preservar les colònies d''abelles quan sigui possible.', 'bomb_t16_assistencies_tecniques', (select id from public.topics where slug = 'bomb-t16-assistencies-tecniques'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-16-MAN.ATXX.000.pdf'), 'MAN.ATXX.000, § himenòpters', 'El criteri operatiu dels Bombers de la Generalitat estableix que només s’ha d’intervenir quan existeix risc immediat per a persones o béns en espais públics o privats amb afectació', null, 'a2ef0b08914ac23079d0bf2022a3a5ffa10dc4fad92340abe0804e5c9809ebc7', false
