  select 'Segons el manual de comunicacions per ràdio, quina és l''estructura recomanada per iniciar una comunicació?', 'S''anomena primer qui rep i després qui emet; en aquest primer missatge no cal dir {CANVI}.', 'bomb_t17_comunicacions_radio', (select id from public.topics where slug = 'bomb-t17-comunicacions-radio'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-17-MAN.COMU.000.pdf'), 'MAN.COMU.000, § ordre d''inici', 'L’estructura recomanada per iniciar la comunicació és que primer s’anomena la unitat receptora del missatge, i després s’identifica l’emissor.', null, '45bafbf58a30ca1d768cf0533b6762288cd59149781e00abcd9bc1fe14f6d902', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '45bafbf58a30ca1d768cf0533b6762288cd59149781e00abcd9bc1fe14f6d902')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Primer s''identifica l''emissor i després la unitat receptora.', false), ('B', 'Primer es diu «CANVI» i després el missatge.', false), ('C', 'Primer s''anomena la unitat receptora i després s''identifica l''emissor.', true), ('D', 'Només cal dir el missatge, sense identificacions.', false)) as v(label, body, ok)
)
