  select 'Segons el manual de conducció, la finalitat de la conducció d''emergència és:', 'L''objectiu no és només arribar ràpid sinó de manera segura i operativa.', 'bomb_t19_conduccio_mecanica', (select id from public.topics where slug = 'bomb-t19-conduccio-mecanica'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-19-MAN.EQIP.002.pdf'), 'MAN.EQIP.002, § conducció d''emergència', 'La finalitat no és escurçar el temps a qualsevol preu, sinó reduir els riscos en el trajecte i minimitzar el temps global de la intervenció.', null, 'ade5f862bdd47e996b847921740f3ffd357d6c8c860e771c685a18e450e3f37d', false
