  select 'Segons el manual de conducció, segons la normativa actual, els dispositius acústics dels vehicles d''emergència:', 'La sirena va sempre amb els llums i només en serveis d''urgència.', 'bomb_t19_conduccio_mecanica', (select id from public.topics where slug = 'bomb-t19-conduccio-mecanica'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-19-MAN.EQIP.002.pdf'), 'MAN.EQIP.002, § sirenes', 'La normativa actual estableix que només poden utilitzar-se durant la prestació de serveis d’urgència, i sempre de forma simultània amb la senyalització lluminosa.', null, '647be85c7cef01c8d4c04aca57841ccfd921b3459de9c7d294c6a0dd0ce2fef0', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '647be85c7cef01c8d4c04aca57841ccfd921b3459de9c7d294c6a0dd0ce2fef0')
