  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'No poden suportar pesos elevats.', false), ('B', 'Requereixen més manteniment que les suspensions pneumàtiques.', false), ('C', 'Són poc resistents i duradors.', false), ('D', 'Ofereixen menys confort perquè transmeten més vibracions a la cabina.', true)) as v(label, body, ok)
)
