with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual d''EPI d''intervenció en emergències, quines normes estableixen el marc legal i tècnic de l''ús dels equips de protecció individual?', 'La LPRL i el RD 773/1997 regulen l''ús dels EPI quan el risc no es pot eliminar amb protecció col·lectiva o organitzativa.', 'bomb_t20_epi_intervencio', (select id from public.topics where slug = 'bomb-t20-epi-intervencio'), 1, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-20-MAN.SEGU.000.pdf'), 'MAN.SEGU.000, § marc legal', 'La Llei 31/1995 de Prevenció de Riscos Laborals i el Reial decret 773/1997 estableixen el marc legal i tècnic que garanteix l’ús adequat dels equips de protecció individual (EPI) quan no és possible eliminar o reduir suficientment els perills mitjançant protecció col·lectiva o mesures organitzatives.', null, '044b3bb83b127387b30bdd2f8c91f15bb70dbb553f356294e49f0bac6fb6d3c7', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '044b3bb83b127387b30bdd2f8c91f15bb70dbb553f356294e49f0bac6fb6d3c7')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La Llei 17/2015 i el Decret 276/2016.', false), ('B', 'El Reial decret 513/2017 i la Llei 3/2010.', false), ('C', 'El Codi de circulació i la Llei 5/1994.', false), ('D', 'La Llei 31/1995 de prevenció de riscos laborals i el Reial decret 773/1997.', true)) as v(label, body, ok)
)
