with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual d''EPI, què són els pictogrames dels equips de protecció?', 'Els pictogrames permeten distingir ràpidament les prestacions dels equips, a més de la categoria.', 'bomb_t20_epi_intervencio', (select id from public.topics where slug = 'bomb-t20-epi-intervencio'), 1, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-20-MAN.SEGU.000.pdf'), 'MAN.SEGU.000, § pictogrames', 'Els pictogrames són símbols normalitzats que indiquen de manera ràpida i visual el tipus de protecció que ofereix cada equip i davant de quin risc actua.', null, '365288ceee504fdcb785eeb8fb2bcc476cf8aee72f8b83281bac639bfb4a4bea', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '365288ceee504fdcb785eeb8fb2bcc476cf8aee72f8b83281bac639bfb4a4bea')
  returning id
), o as (
