  select 'Segons el manual d''EPI, què vol dir ERA?', 'L''ERA assegura aire net en ambients hostils i és obligatori en moltes intervencions.', 'bomb_t20_epi_intervencio', (select id from public.topics where slug = 'bomb-t20-epi-intervencio'), 1, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-20-MAN.SEGU.000.pdf'), 'MAN.SEGU.000, § ERA obligatori', 'Els equips més habituals són els ERA (Equips de Respiració Autònoma), que asseguren aire net en ambients hostils, i les màscares filtrants, que permeten treballar en atmosferes amb presència controlada de contaminants.', null, '4e4d2560cc56998fc6d44d8848984b198dae9cb363152cdbd50e9a048e83e11b', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '4e4d2560cc56998fc6d44d8848984b198dae9cb363152cdbd50e9a048e83e11b')
