with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual d''introducció a la gestió d''emergències i protecció civil, la gestió d''emergències és:', 'La gestió d''emergències actua a totes les fases: abans, durant i després.', 'bomb_t21_gestio_emergencies_proteccio_civil', (select id from public.topics where slug = 'bomb-t21-gestio-emergencies-proteccio-civil'), 1, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.GRAL.001-Tema-21-Intro.-gestio-emergencies-i-P.Civil.pdf'), 'MAN.GRAL.001, § gestió d''emergències', 'Introducció a la gestió d’emergències La gestió d’emergències és l’organització i l’administració dels recursos, responsabilitats i capacitats necessàries per afrontar tots els aspectes d’una emergència, abans, durant i després que es produeixi.', null, '5414608cfffc6411697876c121a4e63a25c5f6c17acffcdf8e0a05fad03e5cc9', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '5414608cfffc6411697876c121a4e63a25c5f6c17acffcdf8e0a05fad03e5cc9')
  returning id
