with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual d''incendis forestals, què és la paradoxa de l''extinció?', 'L''eficàcia en l''extinció acumula combustible i augmenta la intensitat dels grans incendis.', 'bomb_t25_incendis_forestals', (select id from public.topics where slug = 'bomb-t25-incendis-forestals'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-25-MAN.INVE.000.pdf'), 'MAN.INVE.000, § paradoxa de l''extinció', 'Això és el que es coneix com la paradoxa de l’extinció; com més eficaços som apagant incendis, els pocs que se''ns escapen són cada vegada més intensos, més potents i més destructius.', null, '91a89a2eb72ddf2f5a709ce53526932408a39ff8214a1155cd53ed930758d540', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '91a89a2eb72ddf2f5a709ce53526932408a39ff8214a1155cd53ed930758d540')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Com més eficaços som apagant incendis, els pocs que s''escapen són cada vegada més intensos i destructius.', true), ('B', 'Que com més aigua es llança, més es propaga el foc.', false), ('C', 'Que els incendis petits cremen més superfície que els grans.', false), ('D', 'Que els mitjans aeris són menys eficaços que els terrestres.', false)) as v(label, body, ok)
)
