  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual d''incendis forestals, un foc convectiu (de combustible) es caracteritza perquè:', 'Pot donar lloc a pirocúmuls o pirocumulonimbus.', 'bomb_t25_incendis_forestals', (select id from public.topics where slug = 'bomb-t25-incendis-forestals'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-25-MAN.INVE.000.pdf'), 'MAN.INVE.000, § foc convectiu', 'Foc convectiu (de combustible) Aquest tipus d’incendi té lloc quan l’acumulació de combustible és tan gran que la intensitat del foc és capaç de generar el seu propi microclima, amb corrents d’aire i dinàmiques internes.', null, 'd8a5efe9dfa6bf02c7e497a222d5dd4927065c92ee0a0753a0f518e0414990ef', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'd8a5efe9dfa6bf02c7e497a222d5dd4927065c92ee0a0753a0f518e0414990ef')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'L''acumulació de combustible és tan gran que el foc genera el seu propi microclima.', true), ('B', 'El vent general n''és l''únic motor.', false), ('C', 'Només es dona de nit.', false), ('D', 'Es propaga exclusivament per superfície.', false)) as v(label, body, ok)
)
