with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el CPS del manual d''incendis forestals, un foc a la base d''un pendent, orientat al sud a les 12 del migdia i amb vent del sud, té una alineació de:', 'Puja (+1), a favor de vent (+1) i sobre combustible calent (+1).', 'bomb_t25_incendis_forestals', (select id from public.topics where slug = 'bomb-t25-incendis-forestals'), 3, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-25-MAN.INVE.000.pdf'), 'MAN.INVE.000, § plena alineació', 'Exemple: si tenim un foc a la base d’un pendent, orientat al sud a les 12 del migdia i amb vent del sud, tenim plena alineació perquè el foc pot ascendir (+1) a favor de vent (+1) i sobre un combustible calent (+1), és a dir 3/3.', null, '76b841e06fb952ea403cbe014d22dc93fb86f499890b887b7197e854591e1afc', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '76b841e06fb952ea403cbe014d22dc93fb86f499890b887b7197e854591e1afc')
