  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual d''incendis forestals, què pot passar en el «desplom de columna» (downdraft) d''un pirocumulonimbus?', 'El downdraft genera vents descendents intensos i imprevisibles.', 'bomb_t25_incendis_forestals', (select id from public.topics where slug = 'bomb-t25-incendis-forestals'), 3, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-25-MAN.INVE.000.pdf'), 'MAN.INVE.000, § downdraft', 'En el cas del pirocumulunimbus es pot donar un procés conegut com “desplom de columna” (downdraft), que genera forts vents descendents que poden ampliar el perímetre de forma sobtada i intensa en qualsevol direcció.', null, 'd177f47fd4f52bc26b2948d974d5675b82275d6df0814be0eba4322876760284', false
