  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '814af0b09b218dc9eaf1059802383f47bdf7d321a90d355c6e74c7029eb9459d')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Qualsevol foc en un aparcament.', false), ('B', 'Només el foc del motor d''un turisme.', false), ('C', 'Qualsevol foc no controlat que afecta un mitjà de transport terrestre autopropulsat que es desplaça per via rodada.', true), ('D', 'Qualsevol foc a la via pública.', false)) as v(label, body, ok)
)
