  select q.id, v.label, v.body, v.ok from q, (values ('A', 'A sotavent.', false), ('B', 'A sobrevent.', true), ('C', 'Pel davant del capó.', false), ('D', 'Per darrere, en línia amb l''eix.', false)) as v(label, body, ok)
)
