with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual d''intervenció bàsica en accidents de mobilitat viària, què s''entén per accident de mobilitat?', 'La definició inclou danys materials, ambientals o personals.', 'bomb_t32_accidents_mobilitat_viaria', (select id from public.topics where slug = 'bomb-t32-accidents-mobilitat-viaria'), 1, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-32-MAN.SVVH.000.pdf'), 'MAN.SVVH.000, § accident de mobilitat', 'Els accidents de mobilitat viària Entenem per accident de mobilitat qualsevol incident que implica un o més vehicles en moviment o aturats, que causa danys materials (vehicles, infraestructures, càrregues), ambientals (vessaments, incendis, contaminació) i/o personals (ferits lleus, greus o víctimes mortals) i que requereix una resposta dels serveis d’emergència.', null, '28288ba4b25af8d0a4d4ef884f600527b6536af008eb0894de26caba83a887ab', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '28288ba4b25af8d0a4d4ef884f600527b6536af008eb0894de26caba83a887ab')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Només els accidents amb víctimes mortals.', false), ('B', 'Qualsevol incident amb un o més vehicles, en moviment o aturats, que causa danys materials, ambientals i/o personals i requereix resposta dels serveis d''emergència.', true), ('C', 'Només les col·lisions entre dos turismes.', false), ('D', 'Qualsevol avaria mecànica a la via.', false)) as v(label, body, ok)
)
