  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Els autocars són urbans i els autobusos interurbans de llarg recorregut.', false), ('B', 'Els autobusos no tenen sortides d''emergència.', false), ('C', 'Als autocars els passatgers viatgen sempre asseguts; als autobusos molts poden anar dempeus.', true), ('D', 'No hi ha cap diferència.', false)) as v(label, body, ok)
)
