with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual d''accidents de mobilitat, quina alçada màxima estableix la normativa per a un autobús o autocar?', 'Amplada fins a 2,55 m (2,60 en casos especials) i longitud entre 13,5 i 18,75 m.', 'bomb_t32_accidents_mobilitat_viaria', (select id from public.topics where slug = 'bomb-t32-accidents-mobilitat-viaria'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-32-MAN.SVVH.000.pdf'), 'MAN.SVVH.000, § dimensions', 'Dimensions i pesos Les dimensions d’un autobús o autocar poden variar segons la configuració, però la normativa estableix uns límits generals: una alçada màxima de 4 metres, una amplada de fins a 2,55 metres (2,60 m en casos especials) i una longitud que oscil·la entre 13,5 i 18,75 metres, segons el nombre d’eixos o si és articulat.', null, '9aca3dd61ab092d12e0a2a102cbf6b5719454af51253669631ccfd9e6ef3ba70', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '9aca3dd61ab092d12e0a2a102cbf6b5719454af51253669631ccfd9e6ef3ba70')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', '2,55 metres.', false), ('B', '3 metres.', false), ('C', '4 metres.', true), ('D', '5,5 metres.', false)) as v(label, body, ok)
)
