insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"La Constitució espanyola: estructura (títol preliminar, títols I-X, disposicions) i valors superiors"},{"n":"2","title":"Corts Generals, Govern, poder judicial i Tribunal Constitucional"},{"n":"3","title":"Reforma constitucional: procediment ordinari (art. 167) i agreujat (art. 168)"},{"n":"4","title":"L''Estatut d''autonomia de Catalunya: estructura, símbols, capitalitat i Aran"},{"n":"5","title":"Institucions de la Generalitat: Parlament, Presidència, Govern i institucions de control"},{"n":"6","title":"Organització de l''Administració catalana: departaments, secretaries generals i forma de les disposicions"},{"n":"7","title":"Competència de la Generalitat en protecció civil i extinció d''incendis (art. 132 EAC)"}]'::jsonb, '["§ Estat social i democràtic CE: «España se constituye en un Estado social y democrático de Derecho»","§ forma política CE: «La forma política del Estado español es la Monarquía parlamentaria.»","§ Corts Generals CE: «Las Cortes Generales representan al pueblo español y están formadas por el Congreso de los Diputados y el Senado.»","§ reforma ordinària CE: «Los proyectos de reforma constitucional deberán ser aprobados por una mayoría de tres quintos de cada una de las Cámaras.»","§ Estatut EAC: «Cataluña, como nacionalidad, ejerce su autogobierno constituida en Comunidad Autónoma de acuerdo con la Constitución y con el presente Estatuto, que es su norma institucional básica.»","§ Generalitat EAC: «La Generalitat está integrada por el Parlamento, la Presidencia de la Generalitat, el Gobierno y las demás instituciones que establece el Capítulo V, del Título II.»","§ Govern EAC: «El Gobierno es el órgano superior colegiado que dirige la acción política y la Administración de la Generalitat.»","§ departaments Llei 13/2008: «El Gobierno se organiza en departamentos, que integran la Administración de la Generalidad.»","§ secretaria general Llei 13/2008: «En cualquier caso, cada departamento dispone de una secretaría general.»","§ protecció civil EAC: «Corresponde a la Generalitat la competencia exclusiva en materia de protección civil»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229'), 'https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229', null, null, null, 'Otras normas citadas: EAC (https://www.boe.es/buscar/act.php?id=BOE-A-2006-13087), Llei 13/2008 (https://www.boe.es/buscar/act.php?id=BOE-A-2008-19526)'
  from public.topics t where t.slug = 'bomb-t01-constitucio-estatut-generalitat'
on conflict (topic_id, locale) do update
