insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"Llei 31/1995: objecte, àmbit d''aplicació i definicions"},{"n":"2","title":"Principis de l''acció preventiva"},{"n":"3","title":"Equips de treball i mitjans de protecció; risc greu i imminent"},{"n":"4","title":"Drets i obligacions de l''empresari i dels treballadors"},{"n":"5","title":"Serveis de prevenció"},{"n":"6","title":"Consulta i participació: delegats de prevenció i comitè de seguretat i salut"},{"n":"7","title":"Equips de protecció individual (RD 773/1997): definició, ús, condicions i obligacions"}]'::jsonb, '["§ objecte Llei 31/1995: «La presente Ley tiene por objeto promover la seguridad y la salud de los trabajadores»","§ prevenció Llei 31/1995: «Se entenderá por «prevención» el conjunto de actividades o medidas adoptadas o previstas en todas las fases de actividad de la empresa con el fin de evitar o disminuir los riesgos derivados del trabajo.»","§ protecció civil Llei 31/1995: «Servicios operativos de protección civil y peritaje forense en los casos de grave riesgo, catástrofe y calamidad pública.»","§ col·lectiva abans que individual Llei 31/1995: «Adoptar medidas que antepongan la protección colectiva a la individual.»","§ servei de prevenció Llei 31/1995: «Se entenderá como servicio de prevención el conjunto de medios humanos y materiales necesarios para realizar las actividades preventivas»","§ comitè Llei 31/1995: «El Comité de Seguridad y Salud es el órgano paritario y colegiado de participación»","§ EPI RD 773/1997: «Los equipos de protección individual deberán utilizarse cuando existan riesgos para la seguridad o salud de los trabajadores que no hayan podido evitarse o limitarse suficientemente por medios técnicos de protección colectiva»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-24292'), 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-24292', null, null, null, 'Otras normas citadas: RD 773/1997 (https://www.boe.es/buscar/act.php?id=BOE-A-1997-12735)'
  from public.topics t where t.slug = 'bomb-t03-prevencio-riscos-laborals-epi'
on conflict (topic_id, locale) do update
   set outline = excluded.outline, key_ideas = excluded.key_ideas, glossary = excluded.glossary,
