insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"Llei 19/2020: objecte, àmbit i principis (títol I)"},{"n":"2","title":"Definicions: discriminació directa, indirecta, múltiple, per associació, per error; assetjament i represàlia"},{"n":"3","title":"Àmbits d''aplicació (títol II): ocupació i funció pública, cossos de seguretat"},{"n":"4","title":"Garanties i promoció del dret (títol III): inversió de la càrrega de la prova, nul·litat, reparació"},{"n":"5","title":"Protocol de la Generalitat sobre assetjament sexual i per raó de sexe, orientació sexual, identitat o expressió de gènere"},{"n":"6","title":"Llei 17/2015: objecte i definicions (capítol I)"},{"n":"7","title":"Mecanismes en l''Administració (capítol III): paritat, plans d''igualtat, funció pública"},{"n":"8","title":"Polítiques públiques per a la igualtat (capítol IV)"}]'::jsonb, '["§ objecte Llei 19/2020 Llei 19/2020: «El objeto de la presente ley es garantizar el derecho a la igualdad de trato y a la no discriminación»","§ discriminació directa Llei 19/2020: «Discriminación directa: La discriminación que se produce cuando una persona es tratada de una forma menos favorable que otra en situación análoga»","§ assetjament discriminatori Llei 19/2020: «Acoso discriminatorio: Cualquier comportamiento basado en algunos de los motivos a los que se refiere el artículo 1 que tiene por objetivo atentar contra la dignidad de una persona»","§ càrrega de la prova Llei 19/2020: «se debe aplicar la inversión de la carga de la prueba»","§ assetjament per raó de sexe Llei 17/2015: «Acoso por razón de sexo: cualquier comportamiento que, por motivo del sexo de una persona, se ejerce con el fin de atentar contra su dignidad»","§ representació paritària Llei 17/2015: «ningún sexo supera el 60% del conjunto de personas a que se refiere ni es inferior al 40%»","§ plans d''igualtat Llei 17/2015: «Los entes locales que tienen órganos específicos de representación del personal a su servicio deben aprobar un plan de igualdad de mujeres y hombres»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2021-1663'), 'https://www.boe.es/buscar/act.php?id=BOE-A-2021-1663', null, null, null, 'Otras normas citadas: Llei 17/2015 (https://www.boe.es/buscar/act.php?id=BOE-A-2015-9676)'
  from public.topics t where t.slug = 'bomb-t04-igualtat-no-discriminacio'
