insert into public.sources (title, url, kind, publisher, published_on) values ('Ley 5/1994, de 4 de mayo, de regulación de los servicios de prevención y extinción de incendios y de salvamentos de Cataluña (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-1994-12665', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('bomb-t06-llei-bombers-proteccio-civil', 'Tema 6. Llei 5/1994, de serveis de prevenció i extinció d''incendis i de salvaments, i Llei 4/1997, de protecció civil') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('bombers-generalitat') and t.slug = 'bomb-t06-llei-bombers-proteccio-civil' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"Llei 5/1994: objecte, principis d''actuació i deures de col·laboració ciutadana"},{"n":"2","title":"Personal dels serveis: professionals, voluntaris i bombers d''empresa; condició d''agents de l''autoritat"},{"n":"3","title":"Cos de Bombers de la Generalitat: funcions (art. 13) i organització"},{"n":"4","title":"Escales i categories; accés a bomber de primera"},{"n":"5","title":"Serveis municipals de prevenció i extinció d''incendis"},{"n":"6","title":"Llei 4/1997: objecte, drets i deures, autoprotecció i mesures d''emergència"},{"n":"7","title":"Plans de protecció civil: territorials, especials i d''autoprotecció"},{"n":"8","title":"Estructura: autoritats, CECAT, Comissió de Protecció Civil, municipis"}]'::jsonb, '["§ objecte Llei 5/1994 Llei 5/1994: «La presente Ley tiene por objeto la ordenación general de las acciones y los servicios de prevención y extinción de incendios y de salvamentos en Cataluña»","§ agents de l''autoritat Llei 5/1994: «si están en acto de servicio, tienen la consideración de agentes de la autoridad»","§ coordinació Llei 5/1994: «la máxima autoridad, a efectos de la coordinación de las actuaciones, es el Cuerpo de Bomberos de la Generalidad, a través del mando máximo que intervenga»","§ escala tècnica Llei 5/1994: «Escala técnica, que comprende las categorías de oficial, de sargento, de cabo y de bombero de primera.»","§ protecció civil Llei 4/1997: «Esta Ley regula la protección civil en Cataluña»","§ plans Llei 4/1997: «Los planes de protección civil pueden ser territoriales, especiales y de autoprotección.»","§ CECAT Llei 4/1997: «El CECAT es un órgano Administrativo, sin personalidad jurídica propia, adscrito al Departamento de Gobernación.»","§ municipis Llei 4/1997: «Los municipios son las entidades básicas de la protección civil en Cataluña»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1994-12665'), 'https://www.boe.es/buscar/act.php?id=BOE-A-1994-12665', null, null, null, 'Otras normas citadas: Llei 4/1997 (https://www.boe.es/buscar/act.php?id=BOE-A-1997-14409)'
  from public.topics t where t.slug = 'bomb-t06-llei-bombers-proteccio-civil'
