insert into public.sources (title, url, kind, publisher, published_on) values ('Decret 276/2016, de 19 de juliol, de les funcions de guàrdia i del sistema de comandament dels serveis de prevenció, extinció d''incendis i salvaments de la Generalitat de Catalunya', 'https://portaljuridic.gencat.cat/eli/es-ct/d/2016/07/19/276', 'web_oficial'::public.source_kind, 'Generalitat de Catalunya · Portal Jurídic de Catalunya', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('bomb-t07-guardia-comandament-departament', 'Tema 7. Decret 276/2016, de guàrdia i comandament, i Decret 12/2023, del Departament d''Interior') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('bombers-generalitat') and t.slug = 'bomb-t07-guardia-comandament-departament' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"Decret 276/2016: objecte, concepte i àmbits de la guàrdia (operatiu, coordinació, suport)"},{"n":"2","title":"Modalitats de guàrdia i relleu"},{"n":"3","title":"Àmbit operatiu: cap operatiu, cap territorial, sotscap territorial i cap de sortida"},{"n":"4","title":"Àmbit de coordinació: Sala Central de Bombers, sales de control territorial, parcs i cap de torn"},{"n":"5","title":"Sistema de comandament: concepte, cap d''intervenció i cinc nivells de comandament"},{"n":"6","title":"Decret 12/2023: estructura del Departament i Direcció General de Prevenció, Extinció d''Incendis i Salvaments"},{"n":"7","title":"Estructura organitzativa del Cos: òrgans centrals i territorials, regions d''emergències i parcs"}]'::jsonb, '["§ guàrdia Decret 276/2016: «La guàrdia és la situació de disponibilitat permanent dels serveis de prevenció, extinció d''incendis i salvaments de la Generalitat»","§ cap d''intervenció Decret 276/2016: «Tots els serveis en situacions d''emergència han de ser comandats per un cap d''intervenció, que serà el màxim comandament de la guàrdia present al lloc del sinistre»","§ nivells Decret 276/2016: «El sistema de comandament s''estructura en cinc nivells de comandament»","§ Sala Central Decret 276/2016: «La Sala Central de Bombers és el centre superior de l''àmbit de coordinació de la guàrdia»","§ comandament del Cos Decret 12/2023: «Corresponen al director o directora general de Prevenció, Extinció d''Incendis i Salvaments el comandament del Cos de Bombers de la Generalitat»","§ regions Decret 12/2023: «Centre, Girona, Lleida, Tarragona, les Terres de l''Ebre, Metropolitana Nord i Metropolitana Sud.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://portaljuridic.gencat.cat/eli/es-ct/d/2016/07/19/276'), 'https://portaljuridic.gencat.cat/eli/es-ct/d/2016/07/19/276', null, null, null, 'Otras normas citadas: Decret 12/2023 (https://portaljuridic.gencat.cat/eli/es-ct/d/2023/01/24/12)'
  from public.topics t where t.slug = 'bomb-t07-guardia-comandament-departament'
