insert into public.sources (title, url, kind, publisher, published_on) values ('Cos de Bombers de la Generalitat · MAN.GRAL.008 Manual operatiu bàsic de la teoria del foc i agents extintors (Guia orientativa d''estudi, convocatòria 81/26)', 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-08-MAN.GRAL.008.pdf', 'web_oficial'::public.source_kind, 'Generalitat de Catalunya · Departament d''Interior i Seguretat Pública (DGPEIS)', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('bomb-t08-teoria-foc-agents-extintors', 'Tema 8. Teoria del foc i agents extintors') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('bombers-generalitat') and t.slug = 'bomb-t08-teoria-foc-agents-extintors' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"Reaccions d''oxidació i combustió: tipus segons la velocitat (deflagració i detonació) i el comburent"},{"n":"2","title":"Triangle i tetraedre del foc"},{"n":"3","title":"Combustibles: punts d''inflamació, combustió i autoignició; límits i rang d''inflamabilitat"},{"n":"4","title":"Comburents, fonts d''ignició i condicionants de la combustió (oxigen, superfície, humitat)"},{"n":"5","title":"Transmissió de la calor: conducció, convecció i radiació"},{"n":"6","title":"Fenòmens extrems: backdraft i flashover"},{"n":"7","title":"Productes de la combustió: gasos, fum i residus"},{"n":"8","title":"Teoria de l''extinció: refredament, sufocació, eliminació del combustible i inhibició"},{"n":"9","title":"Classes de foc (UNE-EN 2) i agents extintors: aigua, escumes, pols i gasos"}]'::jsonb, '["§ deflagració MAN.GRAL.008: «És un tipus d''explosió on la combustió es propaga a una velocitat superior a 1 m/s però inferior a la velocitat del so en el medi (subsònica).»","§ detonació MAN.GRAL.008: «És un tipus d''explosió on la combustió es propaga a una velocitat supersònica (superior a la velocitat del so en el medi), creant una potent i destructiva ona de xoc.»","§ comburent MAN.GRAL.008: «La majoria de focs necessiten almenys un 16% d''oxigen a l''atmosfera per mantenir-se.»","§ punt d''inflamació MAN.GRAL.008: «És la temperatura mínima a la qual un combustible emet prou vapors per formar una barreja inflamable amb l''aire, que pot encendre''s momentàniament en presència d''una font d''ignició externa (una flama, una guspira, etc.).»","§ punt de combustió MAN.GRAL.008: «El punt de combustió és sempre lleugerament superior al punt d''inflamació (normalment uns pocs graus més alt), ja que requereix una generació de vapors més sostinguda per mantenir la flama activa.»","§ autoignició MAN.GRAL.008: «És la temperatura a la qual un combustible s''encén espontàniament sense necessitat de cap font d''ignició externa.»","§ rang d''inflamabilitat MAN.GRAL.008: «Com més ampli sigui aquest rang, més gran és el risc que la substància formi una barreja perillosa amb capacitat d’encendre’s.»","§ transmissió de la calor MAN.GRAL.008: «Hi ha tres mecanismes principals de transmissió de la calor: conducció, convecció i radiació.»","§ backdraft MAN.GRAL.008: «Backdraft El backdraft és una reignició explosiva d''un incendi que es troba en una fase de ventilació limitada.»","§ flashover MAN.GRAL.008: «Flashover El flashover és la transició ràpida d''un incendi localitzat a un incendi totalment desenvolupat en un espai, on totes les superfícies combustibles s''encenen gairebé simultàniament.»","§ productes de la combustió MAN.GRAL.008: «El monòxid de carboni (CO) és el producte de combustió incompleta més comú i perillós.»","§ sufocació MAN.GRAL.008: «La sufocació consisteix en eliminar o reduir la concentració d''oxigen per sota d''aquest nivell (o el que sigui crític per a un combustible particular).»","§ classes de foc MAN.GRAL.008: «No existeix una Classe E de focs elèctrics.»","§ aigua MAN.GRAL.008: «Quan l''aigua es vaporitza, genera un gran volum de vapor (aproximadament 1.700 litres de vapor per cada litre d''aigua).»","§ pols ABC MAN.GRAL.008: «Està composta principalment per fosfat monoamònic.»","§ gasos MAN.GRAL.008: «No són eficaços en incendis de materials sòlids amb brases profundes (Classe A), ja que no penetren en el material.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-08-MAN.GRAL.008.pdf'), 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-08-MAN.GRAL.008.pdf', null, null, null, null
  from public.topics t where t.slug = 'bomb-t08-teoria-foc-agents-extintors'
