insert into public.sources (title, url, kind, publisher, published_on) values ('Cos de Bombers de la Generalitat · MAN.GRAL.003 Manual operatiu bàsic de Física (Guia orientativa d''estudi, convocatòria 81/26)', 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-09-MAN.GRAL.003.pdf', 'web_oficial'::public.source_kind, 'Generalitat de Catalunya · Departament d''Interior i Seguretat Pública (DGPEIS)', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('bomb-t09-fisica', 'Tema 9. Física') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('bombers-generalitat') and t.slug = 'bomb-t09-fisica' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"Magnituds i unitats: fonamentals i derivades, SI, equivalències i prefixos"},{"n":"2","title":"Magnituds escalars i vectorials; forces i parells de forces"},{"n":"3","title":"Geometria i trigonometria aplicades: àrees, volums, Pitàgores, sinus, cosinus i tangent"},{"n":"4","title":"Cinemàtica: MRU i MUA"},{"n":"5","title":"Dinàmica: lleis de Newton i quantitat de moviment"},{"n":"6","title":"Treball, energia (cinètica i potencial), forces conservatives i fregament"},{"n":"7","title":"Potència, rendiment i eficiència"},{"n":"8","title":"Màquines simples: palanques, pla inclinat, torn i politges"}]'::jsonb, '["§ magnituds escalars MAN.GRAL.003: «Magnituds escalars Una magnitud escalar es defineix completament amb un número i la unitat corresponent.»","§ magnituds vectorials MAN.GRAL.003: «Magnituds vectorials Una magnitud vectorial requereix més informació per ser definida.»","§ parell de forces MAN.GRAL.003: «Parell de Forces Un parell de forces és un sistema de dues forces iguals en mòdul i direcció, però de sentit contrari, que actuen sobre un mateix objecte en punts d''aplicació diferents.»","§ parell de forces MAN.GRAL.003: «Es mesura en newton-metre (Nm), i es calcula multiplicant el valor d''una de les forces per la distància que separa els seus punts d''aplicació.»","§ MRU MAN.GRAL.003: «Moviment Rectilini Uniforme (MRU) És el model més senzill de moviment en què un cos es mou en línia recta a velocitat constant, és a dir ni accelera ni desaccelera (a=0).»","§ llei d''inèrcia MAN.GRAL.003: «Llei d''Inèrcia Un cos en repòs continuarà en repòs, i un cos en moviment continuarà en moviment rectilini uniforme, a menys que una força externa actuï sobre ell.»","§ llei fonamental de la dinàmica MAN.GRAL.003: «La força neta que actua sobre un cos és directament proporcional a l''acceleració que experimenta i a la seva massa.»","§ llei d''acció-reacció MAN.GRAL.003: «Llei d''Acció-Reacció Aquesta llei afirma que per a cada força d''acció, hi ha una força de reacció que és igual en magnitud i oposada en direcció.»","§ energia cinètica MAN.GRAL.003: «Energia cinètica (Ec) És l''energia que té un cos a causa del seu moviment.»","§ energia potencial MAN.GRAL.003: «L’energia potencial gravitacional és l''energia que té un objecte a causa de la seva alçada.»","§ fregament MAN.GRAL.003: «Aquesta força actua sempre en sentit contrari al moviment i tendeix a frenar-lo.»","§ rendiment MAN.GRAL.003: «L''eficiència sempre és inferior al 100% perquè les forces no conservatives, com el fregament i la resistència aerodinàmica, transformen una part de l''energia en calor o turbulències de l’aire, que no podem aprofitar per fer la tasca que volem.»","§ palanca MAN.GRAL.003: «Perquè una palanca estigui en equilibri, els moments que giren en un sentit han de ser iguals als que giren en sentit contrari.»","§ palanca de primer gènere MAN.GRAL.003: «El fulcre es troba entre la força aplicada i la força de sortida.»","§ pla inclinat MAN.GRAL.003: «Pla Inclinat El pla inclinat és una superfície plana que forma un angle amb l''horitzontal, per entendre’ns, una rampa.»","§ politges MAN.GRAL.003: «Politja fixa: no es desplaça respecte al terra, només canvia la direcció de la corda, no ofereix cap avantatge mecànic (AM=1).»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-09-MAN.GRAL.003.pdf'), 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-09-MAN.GRAL.003.pdf', null, null, null, null
  from public.topics t where t.slug = 'bomb-t09-fisica'
