insert into public.sources (title, url, kind, publisher, published_on) values ('Cos de Bombers de la Generalitat · MAN.GRAL.004 Manual operatiu bàsic de Química (Guia orientativa d''estudi, convocatòria 81/26)', 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-10-MAN.GRAL.004.pdf', 'web_oficial'::public.source_kind, 'Generalitat de Catalunya · Departament d''Interior i Seguretat Pública (DGPEIS)', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('bomb-t10-quimica', 'Tema 10. Química') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('bombers-generalitat') and t.slug = 'bomb-t10-quimica' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"Estructura de la matèria: àtoms, nombre atòmic i màssic, isòtops i ions"},{"n":"2","title":"Polaritat de les molècules"},{"n":"3","title":"Enllaços químics: iònic, covalent i metàl·lic; forces intermoleculars"},{"n":"4","title":"Reaccions químiques: tipus, redox, neutralització i conservació de la massa"},{"n":"5","title":"Estequiometria: mols, volum molar i reactiu limitant"},{"n":"6","title":"Estats de la matèria, canvis d''estat i lleis dels gasos"},{"n":"7","title":"Termoquímica: reaccions exotèrmiques i endotèrmiques, calor específica"},{"n":"8","title":"Hidrocarburs: alcans, alquens i alquins"}]'::jsonb, '["§ nombre atòmic MAN.GRAL.004: «El nombre atòmic (Z) és el nombre de protons que té el nucli de l’àtom.»","§ nombre màssic MAN.GRAL.004: «El nombre màssic (A) és el total de partícules del nucli, és a dir, la suma de protons i neutrons (A = Z + N).»","§ isòtops MAN.GRAL.004: «Tots els isòtops d’un element tenen el mateix nombre de protons, però varien en el nombre de neutrons.»","§ ions MAN.GRAL.004: «Quan tenim més o menys electrons del normal parlem d''ions, i és el que ens marca la càrrega elèctrica de l''àtom.»","§ enllaç iònic MAN.GRAL.004: «Enllaç iònic L’enllaç iònic es forma entre un metall, que tendeix a cedir electrons, i un no metall, que tendeix a captar-ne.»","§ enllaç metàl·lic MAN.GRAL.004: «Enllaç metàl·lic L’enllaç metàl·lic és la unió característica dels metalls, en què els àtoms comparteixen els seus electrons més externs.»","§ redox MAN.GRAL.004: «Reaccions oxidació-reducció (redox) Transferència d’electrons entre substàncies; una s’oxida (perd electrons) i l’altra es redueix (guanya electrons).»","§ neutralització MAN.GRAL.004: «Reacció àcid-base (neutralització) Un àcid (HA) i una base (BOH) reaccionen per formar una sal (BA) i aigua.»","§ mols MAN.GRAL.004: «Mols i massa molar La quantitat de matèria s’expressa en mols (mol), on 1 mol correspon al nombre d’Avogadro (6,022·10²³ entitats).»","§ gasos ideals MAN.GRAL.004: «PV=nRT on P és la pressió, V el volum, n el nombre de mols, R la constant de gasos (0,0821 L·atm/mol·K) i T la temperatura en graus Kelvin.»","§ Boyle-Mariotte MAN.GRAL.004: «Llei de Boyle-Mariotte Per una mateixa massa de gas, si no varia la temperatura, la pressió i el volum són inversament proporcionals.»","§ endotèrmica MAN.GRAL.004: «Reacció endotèrmica: absorbeix energia (generalment calor)de l’entorn per poder dur-se a terme.»","§ calor específica MAN.GRAL.004: «Calor específica La calor específica és una propietat característica de cada material.»","§ alcans MAN.GRAL.004: «Rellevància per a bombers: risc d’explosió en espais tancats amb presència de gas butà i/o propà.»","§ alquens MAN.GRAL.004: «Alquens Els alquens són hidrocarburs insaturats amb un doble enllaç C=C.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-10-MAN.GRAL.004.pdf'), 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-10-MAN.GRAL.004.pdf', null, null, null, null
  from public.topics t where t.slug = 'bomb-t10-quimica'
