insert into public.sources (title, url, kind, publisher, published_on) values ('Cos de Bombers de la Generalitat · MAN.GRAL.005 Manual operatiu bàsic d''electricitat (Guia orientativa d''estudi, convocatòria 81/26)', 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-11-MAN.GRAL.005.pdf', 'web_oficial'::public.source_kind, 'Generalitat de Catalunya · Departament d''Interior i Seguretat Pública (DGPEIS)', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('bomb-t11-electricitat', 'Tema 11. Electricitat') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('bombers-generalitat') and t.slug = 'bomb-t11-electricitat' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"Fonaments: sentit i tipus de corrent; conductors, semiconductors i aïllants"},{"n":"2","title":"Magnituds bàsiques: càrrega, intensitat, tensió, resistència, potència i energia"},{"n":"3","title":"Lleis bàsiques: llei d''Ohm, efecte Joule i potència"},{"n":"4","title":"Circuits simples: connexions en sèrie i en paral·lel"},{"n":"5","title":"Corrent altern: tensió eficaç i de pic, monofàsic i trifàsic"},{"n":"6","title":"Potència activa, reactiva i aparent; factor de potència"},{"n":"7","title":"Riscos de l''electricitat: efectes sobre el cos humà, tensió de pas, instal·lacions i materials"}]'::jsonb, '["§ sentit del corrent MAN.GRAL.005: «No obstant això, en la realitat física, els electrons es mouen des del pol negatiu (on hi ha un excés d''electrons) cap al pol positiu (on hi ha una manca d''electrons).»","§ corrent altern MAN.GRAL.005: «Els electrons canvien de sentit periòdicament, invertint el seu sentit de flux.»","§ aïllants MAN.GRAL.005: «Tot i això, si s’arriba a la seva tensió de ruptura poden comportar-se com conductors.»","§ intensitat MAN.GRAL.005: «Intensitat La intensitat de corrent és la quantitat d''electrons (càrrega elèctrica) que passen per un punt d''un circuit en un temps determinat.»","§ resistència MAN.GRAL.005: «Els conductors tenen baixa resistència, mentre que els aïllants tenen una resistència molta alta.»","§ llei d''Ohm MAN.GRAL.005: «Llei d’Ohm La Llei d''Ohm relaciona la tensió, la intensitat i la resistència en un circuit elèctric.»","§ efecte Joule MAN.GRAL.005: «Efecte Joule L’efecte Joule és la transformació d’energia elèctrica en calor quan el corrent circula per un conductor amb resistència.»","§ sèrie MAN.GRAL.005: «Connexió en sèrie En una connexió en sèrie, els receptors es connecten un darrere l''altre, formant un únic camí per al corrent.»","§ paral·lel MAN.GRAL.005: «Connexió en paral·lel En una connexió en paral·lel, els receptors es connecten de manera que cada un té el seu propi camí independent des de la font de tensió.»","§ tensió eficaç MAN.GRAL.005: «A Europa la tensió eficaç entre fase i neutre és de 230 V.»","§ trifàsic MAN.GRAL.005: «Es basa en tres corrents alterns desfasats entre sí 120°.»","§ factor de potència MAN.GRAL.005: «Es representa amb el cosinus de l''angle de desfasament entre la tensió i la intensitat (cos(ϕ)).»","§ cos humà MAN.GRAL.005: «El cos humà és conductor Per a l''electricitat, el cos humà és una càrrega més dins d''un circuit elèctric, i apliquen les mateixes lleis que hem vist anteriorment.»","§ cremades MAN.GRAL.005: «El corrent elèctric que travessa el cos es converteix en calor (efecte Joule), provocant cremades internes i externes molt greus, sovint devastadores, en els punts d''entrada i sortida del corrent i al llarg del seu recorregut.»","§ atmosferes explosives MAN.GRAL.005: «En ambients amb gasos, vapors o pols inflamables, una espurna o un arc elèctric pot provocar una explosió devastadora.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-11-MAN.GRAL.005.pdf'), 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-11-MAN.GRAL.005.pdf', null, null, null, null
  from public.topics t where t.slug = 'bomb-t11-electricitat'
