insert into public.sources (title, url, kind, publisher, published_on) values ('Cos de Bombers de la Generalitat · MAN.GRAL.007 Manual operatiu bàsic sobre instal·lacions (Guia orientativa d''estudi, convocatòria 81/26)', 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.GRAL.007-Tema-12.-Installacions.pdf', 'web_oficial'::public.source_kind, 'Generalitat de Catalunya · Departament d''Interior i Seguretat Pública (DGPEIS)', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('bomb-t12-installacions', 'Tema 12. Instal·lacions elèctriques, d''aigua i de gas') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('bombers-generalitat') and t.slug = 'bomb-t12-installacions' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"Xarxa elèctrica: generació, transport i distribució; alta, mitja i baixa tensió"},{"n":"2","title":"Instal·lacions d''enllaç (CGP, centralització de comptadors) i instal·lacions interiors"},{"n":"3","title":"Proteccions: magnetotèrmics, IGA i diferencials; presa de terra"},{"n":"4","title":"Aparells de mesura i regles de seguretat: les 5 regles d''or"},{"n":"5","title":"Instal·lacions d''aigua: escomesa, instal·lació general, muntants i evacuació d''aigües residuals i pluvials"},{"n":"6","title":"Instal·lacions de gas: gas natural, GLP, claus de tall i aparells gasodomèstics"}]'::jsonb, '["§ alta tensió MAN.GRAL.007: «Qualsevol intervenció en aquests àmbits, com a línies d''alta tensió, subestacions o centres de transformació, s''ha de fer sempre acompanyat de personal de la companyia elèctrica.»","§ baixa tensió MAN.GRAL.007: «Baixa tensió (BT), fins a 1000 V en corrent altern, xarxa de distribució secundària o local.»","§ CGP MAN.GRAL.007: «El tram final de la xarxa de baixa tensió és l’escomesa que arriba a la caixa general de protecció (CGP), que és el punt frontera entre la distribució i la instal·lació del client o abonat.»","§ instal·lacions d''enllaç MAN.GRAL.007: «Instal·lacions d’enllaç Les instal·lacions d’enllaç són la part de la instal·lació que uneix la xarxa de distribució amb els dispositius generals de comandament i protecció de les instal·lacions interiors dels usuaris.»","§ IGA MAN.GRAL.007: «L’IGA (Interruptor General Automàtic) és un magnetotèrmic que es col·loca al principi del quadre elèctric i protegeix tota la instal·lació domèstica.»","§ diferencials MAN.GRAL.007: «Diferencials Els diferencials són la protecció més important per a la seguretat de les persones, ja que detecten fuites de corrent a terra.»","§ diferencials MAN.GRAL.007: «30 mA: obligatori a habitatges; nivell de protecció per a persones.»","§ 5 regles d''or MAN.GRAL.007: «Les 5 regles d’or La manera més segura d’intervenir en una instal·lació elèctrica és treballar-hi sense tensió.»","§ detectors de tensió MAN.GRAL.007: «Per tant, l''absència de senyal no eximeix de fer una segona comprovació amb un voltímetre per confirmar que realment no hi ha tensió.»","§ aigua MAN.GRAL.007: «Clau de tall general Serveix per interrompre el subministrament a tot l’edifici.»","§ muntants MAN.GRAL.007: «Ascendents o muntants Porten l’aigua verticalment pels pisos.»","§ evacuació MAN.GRAL.007: «L’evacuació es fa principalment per gravetat, mitjançant conductes verticals (baixants) i desguassos, amb canonades habitualment de PVC gris.»","§ gas natural MAN.GRAL.007: «El gas natural és menys dens que l’aire i té un alt poder calorífic, cosa que el fa molt eficient com a combustible.»","§ GLP MAN.GRAL.007: «El subministrament més habitual dels habitatges que no estan connectats a la xarxa de gas canalitzat, és el gas butà envasat en bombones, i els elements principals de la instal·lació de gas butà són la bombona, el regulador de pressió i el tub flexible.»","§ clau d''abonat MAN.GRAL.007: «Separa la instal·lació comuna de la instal·lació individual i permet interrompre el pas de gas només a aquell abonat.»","§ ventilació MAN.GRAL.007: «Permeten l’entrada i renovació d’aire des de l’exterior, garantint una combustió correcta dels aparells i evitant la formació de monòxid de carboni (CO), un gas altament tòxic.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.GRAL.007-Tema-12.-Installacions.pdf'), 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.GRAL.007-Tema-12.-Installacions.pdf', null, null, null, null
  from public.topics t where t.slug = 'bomb-t12-installacions'
