insert into public.sources (title, url, kind, publisher, published_on) values ('Cos de Bombers de la Generalitat · MAN.GRAL.009 Manual operatiu bàsic sobre hidràulica i bombes (Guia orientativa d''estudi, convocatòria 81/26)', 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-13-MAN.GRAL.009.pdf', 'web_oficial'::public.source_kind, 'Generalitat de Catalunya · Departament d''Interior i Seguretat Pública (DGPEIS)', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('bomb-t13-hidraulica-bombes', 'Tema 13. Hidràulica i bombes') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('bombers-generalitat') and t.slug = 'bomb-t13-hidraulica-bombes' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"Propietats físiques dels líquids: densitat, viscositat, pressió de vapor, tensió superficial i capil·laritat"},{"n":"2","title":"Hidrostàtica: pressió, unitats, pressió atmosfèrica, absoluta i relativa; principi d''Arquimedes"},{"n":"3","title":"Hidrodinàmica: cabal, equació de continuïtat i equació de Bernoulli"},{"n":"4","title":"Efecte Venturi i teorema de Torricelli"},{"n":"5","title":"Pèrdues de càrrega; mànegues en sèrie i en paral·lel"},{"n":"6","title":"Fenòmens associats: cop d''ariet i cavitació"},{"n":"7","title":"Bombes: centrífugues i volumètriques, corbes característiques, hidrant i punt de funcionament"},{"n":"8","title":"Reacció del raig"}]'::jsonb, '["§ densitat MAN.GRAL.009: «Densitat La densitat d’un fluid és la quantitat de massa que conté per unitat de volum.»","§ viscositat MAN.GRAL.009: «L’aigua té una viscositat dinàmica molt baixa, de 0,001 Pa·s.»","§ pressió de vapor MAN.GRAL.009: «Cada líquid té la seva pròpia pressió de vapor que augmenta a mesura que la temperatura puja.»","§ capil·laritat MAN.GRAL.009: «Capil·laritat És la capacitat d’un líquid d’ascendir o descendir per un tub molt estret (com un capil·lar), gràcies a la combinació de la tensió superficial i l’adhesió a les parets.»","§ unitats de pressió MAN.GRAL.009: «1 bar = 10 metres de columna d’aigua»","§ pressió absoluta MAN.GRAL.009: «Pressió absoluta: és la pressió total exercida per un fluid, mesurada des del buit absolut (pressió 0).»","§ Arquimedes MAN.GRAL.009: «Principi d’Arquímedes El Principi d’Arquímedes diu que un cos, total o parcialment submergit en un fluid experimenta una empenta vertical cap amunt (força d''empenta) que és igual al pes del fluid que desplaça.»","§ continuïtat MAN.GRAL.009: «En un fluid incompressible, com l''aigua, l''equació de continuïtat estableix que el cabal és constant en qualsevol punt d''una conducció.»","§ Venturi MAN.GRAL.009: «Efecte Venturi L''efecte Venturi és un fenomen físic que es produeix quan un fluid circula per un conducte tancat que s’estreny, disminueix la seva pressió ja que augmenta la velocitat.»","§ Torricelli MAN.GRAL.009: «Teorema de Torricelli El teorema o llei de Torricelli relaciona la velocitat de sortida d’un líquid per un forat amb l’alçada de líquid que hi ha per sobre del forat.»","§ cop d''ariet MAN.GRAL.009: «Aquesta ona de sobrepressió pot ser diverses vegades superior a la pressió de treball normal del sistema.»","§ cavitació MAN.GRAL.009: «Cavitació La cavitació és un fenomen físic no desitjat que es produeix quan, en una zona del circuit la pressió del líquid baixa tant que es formen bombolles de vapor d’aigua.»","§ bombes MAN.GRAL.009: «Aquestes bombes es classifiquen segons el seu principi de funcionament en dos grans tipus: bombes centrífugues i bombes volumètriques.»","§ bomba volumètrica MAN.GRAL.009: «Per això, la corba pressió/cabal és gairebé una línia recta vertical.»","§ reacció del raig MAN.GRAL.009: «A més pressió l’aigua surt endavant a major velocitat, i més gran és la força de reacció que ha de suportar el bomber.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-13-MAN.GRAL.009.pdf'), 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-13-MAN.GRAL.009.pdf', null, null, null, null
  from public.topics t where t.slug = 'bomb-t13-hidraulica-bombes'
