insert into public.sources (title, url, kind, publisher, published_on) values ('Cos de Bombers de la Generalitat · MAN.GRAL.006 Manual operatiu bàsic de construcció (Guia orientativa d''estudi, convocatòria 81/26)', 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.GRAL.006-Tema-15.-Manual-Op.-basic-construccio.pdf', 'web_oficial'::public.source_kind, 'Generalitat de Catalunya · Departament d''Interior i Seguretat Pública (DGPEIS)', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('bomb-t15-construccio', 'Tema 15. Construcció') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('bombers-generalitat') and t.slug = 'bomb-t15-construccio' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"Comportament estructural: accions, reaccions i esforços"},{"n":"2","title":"Tipus d''esforç: tracció, compressió, flexió, torsió, tallant i vinclament"},{"n":"3","title":"Materials de construcció"},{"n":"4","title":"Fonaments: sabates, llosa i pilots"},{"n":"5","title":"Elements verticals: murs de càrrega, pilars, pantalles i pilastres"},{"n":"6","title":"Elements horitzontals: forjats, bigues i jàsseres"},{"n":"7","title":"Elements no estructurals i jerarquia estructural"},{"n":"8","title":"Sistemes estructurals: murs de càrrega, porticat i grans llums"}]'::jsonb, '["§ accions MAN.GRAL.006: «Accions En el camp de la construcció, el terme “accions” fa referència a totes aquelles forces o influències externes que actuen sobre una edificació al llarg del temps i que poden afectar-ne l’estabilitat.»","§ esforços MAN.GRAL.006: «Esforços Els esforços són les reaccions internes que apareixen dins dels materials i elements estructurals d’una edificació com a resposta directa a les accions que hi actuen.»","§ torsió MAN.GRAL.006: «Torsió La torsió és un gir que tendeix a retorçar l’element.»","§ tallant MAN.GRAL.006: «Tallant L’esforç tallant vol “lliscar” una part de l’element respecte l’altra.»","§ sabates aïllades MAN.GRAL.006: «Sabatilles aïllades S’utilitzen quan les càrregues de l’edifici es concentren en punts concrets, generalment pilars aïllats.»","§ pilar crític MAN.GRAL.006: «És l’element més crític en una estructura porticada: la fallada d’un pilar compromet diversos nivells.»","§ murs de càrrega MAN.GRAL.006: «Murs de càrrega Els murs de càrrega són elements verticals continus que suporten directament els sostres i la coberta.»","§ sistema porticat MAN.GRAL.006: «Sistema de pilars i forjats El sistema de pilars i forjats, també conegut com a sistema porticat, és el model estructural més utilitzat en l’edificació moderna, especialment a partir dels anys 1970.»","§ reformes MAN.GRAL.006: «En emergències, cal extremar la precaució en zones amb fusta, reformes incorrectes o murs debilitats, ja que aquest sistema no tolera bé l’eliminació o degradació de cap element portador.»","§ grans llums MAN.GRAL.006: «Aquests sistemes requereixen una atenció especial en intervencions, ja que la pèrdua d’un únic element (com un pilar, una jàssera o una unió) pot desencadenar el col·lapse total de la coberta, especialment en estructures metàl·liques.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.GRAL.006-Tema-15.-Manual-Op.-basic-construccio.pdf'), 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.GRAL.006-Tema-15.-Manual-Op.-basic-construccio.pdf', null, null, null, null
  from public.topics t where t.slug = 'bomb-t15-construccio'
