insert into public.sources (title, url, kind, publisher, published_on) values ('Cos de Bombers de la Generalitat · MAN.ATXX.000 Intervenció bàsica en assistències tècniques (Guia orientativa d''estudi, convocatòria 81/26)', 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-16-MAN.ATXX.000.pdf', 'web_oficial'::public.source_kind, 'Generalitat de Catalunya · Departament d''Interior i Seguretat Pública (DGPEIS)', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('bomb-t16-assistencies-tecniques', 'Tema 16. Intervenció en assistències tècniques') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('bombers-generalitat') and t.slug = 'bomb-t16-assistencies-tecniques' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"Intervencions amb animals: coneixements generals i seguretat"},{"n":"2","title":"Maniobres segons l''espècie: gossos, gats, ramats, èquids i bòvids, fauna salvatge, aus, rèptils"},{"n":"3","title":"Himenòpters: criteri d''intervenció i espècies"},{"n":"4","title":"Primera assistència a animals"},{"n":"5","title":"Motoserra: parts, tipus i manteniment"},{"n":"6","title":"Valoració prèvia, AGO i tècniques de tall"},{"n":"7","title":"Seguretat i EPI en el tall d''arbrat"},{"n":"8","title":"Obertura de portes en entorn urbà"}]'::jsonb, '["§ animal i emergència MAN.ATXX.000: «Coneixements generals En qualsevol intervenció amb animals, el punt de partida és entendre que l’animal viurà l’emergència com una amenaça.»","§ aus MAN.ATXX.000: «Aus Les aus són animals fràgils, especialment sensibles a fractures d’ales i al trencament de plomes primàries.»","§ serps MAN.ATXX.000: «En el cas de les serps, és recomanable utilitzar ganxos o pinces que permetin mantenir distància de seguretat amb el cap o oferir-los un recinte fosc on entrar i amagar-se per poder-los enretirar del lloc on es troben.»","§ vespa asiàtica MAN.ATXX.000: «Vespa asiàtica (Vespa velutina) Espècie invasora del sud-est asiàtic, més gran que les autòctones i de color fosc amb franges grogues.»","§ cop de calor MAN.ATXX.000: «Cops de calor: és fonamental baixar la temperatura corporal amb ruixats d’aigua, alcohol en zones irrigades, ombra i hidratació progressiva, fins al relleu veterinari.»","§ cadena MAN.ATXX.000: «La cadena és l’element tallant, formada per dents afilades que giren a gran velocitat al voltant de l’espasa.»","§ meteorologia MAN.ATXX.000: «Les condicions meteorològiques adverses, com pluja intensa o vent fort, incrementen de manera significativa la probabilitat d’incidents; per això és imprescindible avaluar prèviament si l’actuació es pot dur a terme amb seguretat o si cal ajornar-la.»","§ treball en alçada MAN.ATXX.000: «Sempre s’ha de prioritzar l’ús d’autoescala i, en treballs a partir de 2 metres, utilitzar tècniques i equips de protecció contra caigudes.»","§ obertura de portes MAN.ATXX.000: «Intervencions amb accés a habitatges en entorn urbà L’obertura de portes és una acció habitual en les actuacions de Bombers, on l’objectiu principal és obtenir un accés ràpid, segur i amb la mínima afectació possible a la porta i a l’immoble, sempre que la situació ho permeti.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-16-MAN.ATXX.000.pdf'), 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-16-MAN.ATXX.000.pdf', null, null, null, null
  from public.topics t where t.slug = 'bomb-t16-assistencies-tecniques'
