insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"La comunicació com a eina essencial en emergències"},{"n":"2","title":"Característiques del missatge operatiu: precís, breu, estructurat i confirmat"},{"n":"3","title":"Principis bàsics: jerarquia, disciplina de xarxa, claredat i marcadors"},{"n":"4","title":"Estructura de la comunicació: inici, {CANVI}, confirmació i alfabet radiofònic"},{"n":"5","title":"Pla de comunicacions i canals: agrupació, servei, directe"},{"n":"6","title":"Migració de canals en grans emergències"},{"n":"7","title":"Xarxa RESCAT: mode xarxa i mode directe"},{"n":"8","title":"Tipus de trucada i missatges: canal, emergència, individual, estat i SDS; pont ràdio i repetidor"}]'::jsonb, '["§ ràdio fonamental MAN.COMU.000: «Tanmateix, cal recordar que, malgrat l’avenç de les eines digitals i geogràfiques, la comunicació per ràdio continua sent l’eina fonamental en qualsevol emergència.»","§ missatge precís MAN.COMU.000: «És precisa: transmet exactament el que es vol dir, amb dades concretes.»","§ marcadors MAN.COMU.000: «Utilitzar marcadors i estructures estàndards Per garantir una comunicació clara i evitar confusions, cal utilitzar frases i marcadors estàndards com ara REBUT, PRIORITARI, CANVI o TALLO.»","§ disciplina de xarxa MAN.COMU.000: «Parlar només quan sigui necessari i evitar saturar la xarxa amb informació innecessària o redundant.»","§ canal del servei MAN.COMU.000: «Canal del servei (canal general o de comandament) És el canal principal de la intervenció, centralitzat pel cap d’intervenció, els comandaments superiors i el Centre de Comandament Avançat (CCA).»","§ mode directe MAN.COMU.000: «Canal en mode directe El mode directe permet que les unitats operatives sobre el terreny es comuniquin sense passar per repetidors o sales de control, utilitzant només la connexió ràdio entre terminals propers.»","§ recurs compartit MAN.COMU.000: «Un dels grans avantatges de la xarxa RESCAT és que permet la coordinació entre serveis d’emergència, ja que utilitza grups de comunicació compartits.»","§ trucada d''emergència MAN.COMU.000: «Trucada d’emergència en mode xarxa És una trucada de canal amb màxima prioritat, iniciada per un transceptor que necessita emetre una alerta urgent.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-17-MAN.COMU.000.pdf'), 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-17-MAN.COMU.000.pdf', null, null, null, null
  from public.topics t where t.slug = 'bomb-t17-comunicacions-radio'
