insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"Funció dels vehicles en les emergències i classificació"},{"n":"2","title":"Mitjans terrestres, aeris i aquàtics"},{"n":"3","title":"Autobombes: BUL, BUP, BRP i BNP"},{"n":"4","title":"Vehicles especials: autoescales (AEA)"},{"n":"5","title":"Grua pesada i grua lleugera; seguretat amb AEA"},{"n":"6","title":"Furgons de salvament i vehicles de riscos tecnològics"},{"n":"7","title":"Vehicles de comandament, sanitaris i de suport"}]'::jsonb, '["§ finalitat de cada vehicle MAN.EQIP.000: «Cada vehicle està dissenyat i equipat amb una finalitat específica, la qual determina la seva estructura, el material transportat i el tipus d’intervencions on és més efectiu.»","§ vehicles d''extinció MAN.EQIP.000: «Autobombes i vehicles d’extinció Els vehicles d’extinció són el pilar fonamental del parc mòbil dels serveis de bombers.»","§ BUP MAN.EQIP.000: «Capacitat d’aigua: entre 3.000 i 4.000 litres.»","§ estabilitat AEA MAN.EQIP.000: «Per garantir l’estabilitat, cal emplaçar l’autoescala en un terreny ferm, estable i planer, utilitzant correctament els estabilitzadors i evitant sobrecàrregues.»","§ comunicació AEA MAN.EQIP.000: «La comunicació clara i coordinada entre l’operador de l’escala, el conductor i el comandament és fonamental durant totes les maniobres.»","§ FSV MAN.EQIP.000: «Són vehicles essencials en serveis de rescat tècnic, i sovint actuen en coordinació amb les autobombes.»","§ vehicles de comandament MAN.EQIP.000: «És des d’aquests vehicles, on es coordinen els recursos operatius, es prenen decisions tàctiques i es manté la comunicació amb els centres o sales de coordinació.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-18-MAN.EQIP.000.pdf'), 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-18-MAN.EQIP.000.pdf', null, null, null, null
