insert into public.sources (title, url, kind, publisher, published_on) values ('Cos de Bombers de la Generalitat · MAN.EQIP.002 Conducció i mecànica (Guia orientativa d''estudi, convocatòria 81/26)', 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-19-MAN.EQIP.002.pdf', 'web_oficial'::public.source_kind, 'Generalitat de Catalunya · Departament d''Interior i Seguretat Pública (DGPEIS)', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('bomb-t19-conduccio-mecanica', 'Tema 19. Conducció i mecànica de vehicles d''emergència') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('bombers-generalitat') and t.slug = 'bomb-t19-conduccio-mecanica' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"La conducció en el marc operatiu del Cos de Bombers"},{"n":"2","title":"Conducció d''emergència: definició i finalitat; característiques dels vehicles pesants"},{"n":"3","title":"Circulació en comboi"},{"n":"4","title":"Senyalització acústica i lluminosa; prioritat de pas"},{"n":"5","title":"Conducció en camins forestals: 4x4, reductora i bloquejadors de diferencials"},{"n":"6","title":"Conducció en condicions adverses: pluja, boira, neu, gel i vent"},{"n":"7","title":"Mecànica bàsica: cadena cinemàtica, tracció, frenada i suspensió"},{"n":"8","title":"Caixa de transferència i reductora"}]'::jsonb, '["§ conducció d''emergència MAN.EQIP.002: «Definició i finalitat La conducció d’emergència fa referència al desplaçament d’un vehicle de bombers quan actua com a vehicle prioritari, és a dir, durant serveis que requereixen una resposta ràpida i immediata per protegir vides, béns o el medi.»","§ vehicles pesants MAN.EQIP.002: «Són molt més pesats, voluminosos i amb un centre de gravetat elevat, fet que afecta greument la maniobrabilitat, el fre i l’estabilitat, sobretot en corbes, rotondes i situacions de frenada sobtada.»","§ ús de la senyalització MAN.EQIP.002: «Ús de sirenes i llums L’ús de la senyalització ha d’estar sempre subordinat a l’objectiu de garantir la seguretat, i no ha de convertir-se en una rutina mecànica.»","§ reductora en moviment MAN.EQIP.002: «La reductora mai no s’ha de connectar amb el vehicle en moviment, ja que podria provocar avaries greus a la transmissió.»","§ tècnica forestal MAN.EQIP.002: «Tècnica de conducció recomanada La conducció en camins forestals ha de ser sempre suau, progressiva i anticipada.»","§ pluja MAN.EQIP.002: «La massa del camió requereix molta més distància per aturar-se en paviment mullat.»","§ gel negre MAN.EQIP.002: «La neu redueix el control sobre el vehicle i empitjora la visibilitat, mentre que el gel —sobretot quan no és visible (gel negre)— pot causar una pèrdua total d’adherència.»","§ caixa de transferència MAN.EQIP.002: «Reductora La caixa de transferència és un mecanisme que reparteix el parell motor de la caixa de canvis cap als eixos davanter i posterior.»","§ 4H a 2H MAN.EQIP.002: «Per passar de 4H a 2H no cal aturar el vehicle.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-19-MAN.EQIP.002.pdf'), 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-19-MAN.EQIP.002.pdf', null, null, null, null
  from public.topics t where t.slug = 'bomb-t19-conduccio-mecanica'
on conflict (topic_id, locale) do update
   set outline = excluded.outline, key_ideas = excluded.key_ideas, glossary = excluded.glossary,
       amendments = excluded.amendments, source_id = excluded.source_id, source_url = excluded.source_url,
       page_from = excluded.page_from, page_to = excluded.page_to, key_ideas_page = excluded.key_ideas_page
 where (n.outline, n.key_ideas, n.glossary, n.amendments)
       is distinct from (excluded.outline, excluded.key_ideas, excluded.glossary, excluded.amendments);
insert into public.sources (title, url, kind, publisher, published_on) values ('Cos de Bombers de la Generalitat · MAN.SEGU.000 EPI d''intervenció en emergències (Guia orientativa d''estudi, convocatòria 81/26)', 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-20-MAN.SEGU.000.pdf', 'web_oficial'::public.source_kind, 'Generalitat de Catalunya · Departament d''Interior i Seguretat Pública (DGPEIS)', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('bomb-t20-epi-intervencio', 'Tema 20. Equips de protecció individual d''intervenció en emergències') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('bombers-generalitat') and t.slug = 'bomb-t20-epi-intervencio' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"Marc legal dels EPI: LPRL i RD 773/1997"},{"n":"2","title":"Categories I, II i III i pictogrames"},{"n":"3","title":"Normes de vestuari: EN 469 (estructural) i EN 15614 (forestal)"},{"n":"4","title":"Casc, guants i botes d''intervenció"},{"n":"5","title":"Nivells d''EPI al Cos: lleuger, pesant i complements"},{"n":"6","title":"Protecció respiratòria: ERA i màscares filtrants"},{"n":"7","title":"Alarmes de l''ERA: avisos de pressió, reserva i home mort"},{"n":"8","title":"Càlcul de consums, capacitat, reserva i autonomia"}]'::jsonb, '["§ categoria II MAN.SEGU.000: «Inclou equips destinats a prevenir danys de gravetat mitjana, com ara protecció auditiva, calçat de seguretat o jaquetes d’alta visibilitat.»","§ casc MAN.SEGU.000: «Casc d’intervenció És l’element clau per a la protecció del cap i la cara davant de múltiples riscos com impactes, projectils, calor, flames, fum, substàncies corrosives i corrents elèctriques.»","§ botes MAN.SEGU.000: «S’han de netejar després de cada servei, assecar lluny de fonts de calor directa i revisar regularment l’estat de la sola, la puntera i les costures.»","§ complements MAN.SEGU.000: «Tot i això, els EPI no són equips tancats: a partir dels components propis de cada modalitat, es poden afegir complements específics que reforcin la protecció davant riscos concrets (tèrmics, mecànics, químics, biològics, etc.).»","§ ERA obligatori MAN.SEGU.000: «En moltes intervencions, especialment en incendis, fuites de productes químics, atmosferes explosives o espais confinats, l’ús de l’equip de respiració autònoma (ERA) és obligatori.»","§ 170 bars MAN.SEGU.000: «170 bars: “Bip-bip” o Arribada a la meitat del temps de treball»","§ revisió prèvia MAN.SEGU.000: «A més, abans de cada ús, cal inspeccionar amb atenció totes les parts mòbils, les juntes i les connexions, per comprovar que no presenten defectes, desgast o danys que puguin comprometre la seguretat i el funcionament correcte de l’equip.»","§ autonomia MAN.SEGU.000: «Autonomia i càlculs operatius L’autonomia operativa és el temps real que el bomber pot treballar abans d’haver d’iniciar la sortida.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-20-MAN.SEGU.000.pdf'), 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-20-MAN.SEGU.000.pdf', null, null, null, null
  from public.topics t where t.slug = 'bomb-t20-epi-intervencio'
