insert into public.sources (title, url, kind, publisher, published_on) values ('Cos de Bombers de la Generalitat · MAN.GRAL.001 Gestió d''emergències i sistema de protecció civil (Guia orientativa d''estudi, convocatòria 81/26)', 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.GRAL.001-Tema-21-Intro.-gestio-emergencies-i-P.Civil.pdf', 'web_oficial'::public.source_kind, 'Generalitat de Catalunya · Departament d''Interior i Seguretat Pública (DGPEIS)', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('bomb-t21-gestio-emergencies-proteccio-civil', 'Tema 21. Introducció a la gestió d''emergències i el sistema de protecció civil') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('bombers-generalitat') and t.slug = 'bomb-t21-gestio-emergencies-proteccio-civil' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"Concepte de gestió d''emergències"},{"n":"2","title":"Cicle de gestió: reducció del risc, preparació, resposta i recuperació"},{"n":"3","title":"La resiliència com a eix transversal"},{"n":"4","title":"El risc: perill, vulnerabilitat i exposició; classificació i construcció social"},{"n":"5","title":"Protecció civil: concepte i evolució"},{"n":"6","title":"Organització competencial i autoritats (Llei 17/2015)"},{"n":"7","title":"Mecanisme europeu de protecció civil"},{"n":"8","title":"Plans de protecció civil: territorials, especials, municipals, PAU i estatals"},{"n":"9","title":"Estructura dels plans: direcció, Comitè d''Emergències, CECAT/CECOPAL i CCA"}]'::jsonb, '["§ protecció civil MAN.GRAL.001: «La protecció civil és el conjunt d''accions i mecanismes que les administracions públiques —i la societat en general— posen en marxa per garantir la seguretat de les persones, els béns i el medi ambient davant situacions de risc col·lectiu o catàstrofes.»","§ perill MAN.GRAL.001: «És la probabilitat que es produeixi un fenomen d’una determinada intensitat.»","§ reduir el risc MAN.GRAL.001: «Per això, per reduir el risc no sempre cal eliminar el perill (que sovint és inevitable), sinó que també es pot reduir la vulnerabilitat o limitar l’exposició.»","§ ajuntaments MAN.GRAL.001: «Àmbit local: la protecció civil municipal Els ajuntaments són la primera baula del sistema.»","§ estat MAN.GRAL.001: «Àmbit estatal: el Ministeri de l’Interior Segons la Llei 17/2015, la direcció global del sistema de protecció civil recau en el Ministeri de l’Interior que és l’autoritat de protecció civil estatal.»","§ pla de protecció civil MAN.GRAL.001: «Els plans de protecció civil Un pla de protecció civil és un document tècnic i operatiu que estableix com s''ha d''organitzar i actuar davant d’un risc determinat o en una situació d’emergència.»","§ PROCICAT MAN.GRAL.001: «Pla territorial de protecció civil de Catalunya, per a riscos generals o situacions que no tenen pla especial.»","§ CECAT MAN.GRAL.001: «El CECAT o CECOPAL com a màxim òrgan de coordinació operativa ja sigui a nivell autonòmic o municipal.»","§ ubicació CCA MAN.GRAL.001: «Habitualment el CCA s’ubica en un lloc segur, però proper a la zona més afectada per permetre una resposta àgil i adaptada al context operatiu.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.GRAL.001-Tema-21-Intro.-gestio-emergencies-i-P.Civil.pdf'), 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.GRAL.001-Tema-21-Intro.-gestio-emergencies-i-P.Civil.pdf', null, null, null, null
  from public.topics t where t.slug = 'bomb-t21-gestio-emergencies-proteccio-civil'
