insert into public.sources (title, url, kind, publisher, published_on) values ('Cos de Bombers de la Generalitat · MAN.COMD.001 Principis i característiques del Sistema de Comandament (Guia orientativa d''estudi, convocatòria 81/26)', 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-22-MAN.COMD.001.pdf', 'web_oficial'::public.source_kind, 'Generalitat de Catalunya · Departament d''Interior i Seguretat Pública (DGPEIS)', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('bomb-t22-sistema-comandament', 'Tema 22. Principis i característiques del Sistema de Comandament del Cos de Bombers') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('bombers-generalitat') and t.slug = 'bomb-t22-sistema-comandament' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"Origen: l''ICS i la seva adaptació, el SISCOM"},{"n":"2","title":"Característiques: terminologia comuna i comunicacions integrades"},{"n":"3","title":"Principis de comandament: comandament únic, relleu i línia de comandament"},{"n":"4","title":"El Pla d''Acció de la Intervenció (PAI)"},{"n":"5","title":"Tram de control"},{"n":"6","title":"Àrees funcionals: comandament, operacions, planificació i logística"},{"n":"7","title":"Organització dels recursos: equip, grup, sector, zona i comandament de la intervenció"},{"n":"8","title":"Instal·lacions de suport al comandament"}]'::jsonb, '["§ ICS implantat MAN.COMD.001: «En aquest sentit, és important remarcar que l’ICS és un dels sistemes de gestió d’incidents més implantat del món.»","§ comandament únic MAN.COMD.001: «Comandament únic El comandament únic es defineix com \"la concentració en un únic comandament de la responsabilitat i autoritat per planificar, dirigir i coordinar una intervenció\".»","§ cap d''intervenció MAN.COMD.001: «A les intervencions, des del seu inici, cal establir i identificar de forma clara el cap d’intervenció, que és qui defineix el Pla d’Acció de la Intervenció (PAI) i estableix els objectius a assolir.»","§ estructura MAN.COMD.001: «El cap d’intervenció és el responsable de determinar l’estructura a desplegar, en funció dels objectius de l''incident i els recursos necessaris.»","§ tram curt MAN.COMD.001: «Cal mantenir el tram de control tan curt i simple com sigui possible.»","§ operacions MAN.COMD.001: «És el responsable de dirigir i supervisar les operacions destinades a establir el control de la situació i restaurar les condicions de normalitat, desenvolupant l''organització sobre el terreny i dirigint els recursos operatius.»","§ grup MAN.COMD.001: «Un grup s''organitza entorn d''una maniobra, i està format per diversos equips que realitzen funcions o tasques específiques.»","§ comandament de la intervenció MAN.COMD.001: «És l''entitat més alta dins l''estructura del SISCOM i és el responsable de la presa de decisions estratègiques i de la gestió global de l’emergència.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-22-MAN.COMD.001.pdf'), 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-22-MAN.COMD.001.pdf', null, null, null, null
  from public.topics t where t.slug = 'bomb-t22-sistema-comandament'
