insert into public.sources (title, url, kind, publisher, published_on) values ('Cos de Bombers de la Generalitat · MAN.SP.000 Prevenció d''incendis bàsica (Guia orientativa d''estudi, convocatòria 81/26)', 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SP.000-Tema-23.-Prevencio-basica-incendis.pdf', 'web_oficial'::public.source_kind, 'Generalitat de Catalunya · Departament d''Interior i Seguretat Pública (DGPEIS)', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('bomb-t23-prevencio-incendis', 'Tema 23. Prevenció bàsica d''incendis') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('bombers-generalitat') and t.slug = 'bomb-t23-prevencio-incendis' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"Protecció activa i passiva"},{"n":"2","title":"Marc normatiu: Llei 3/2010, CTE DB SI, RSCIEI i reglaments específics"},{"n":"3","title":"Accés per l''exterior: vies d''intervenció, espais de maniobra i façanes accessibles"},{"n":"4","title":"Accés per l''interior: vies de penetració protegides"},{"n":"5","title":"Límits a l''extensió de l''incendi: reacció i resistència al foc (R, E, I)"},{"n":"6","title":"Sectorització, façanes, cobertes i mur tallafocs"},{"n":"7","title":"Instal·lacions de protecció i sistemes de ventilació de fums"}]'::jsonb, '["§ règim sancionador MAN.SP.000: «Un altre aspecte innovador d’aquesta Llei és la creació d’un règim sancionador específic que permet corregir els incompliments de la normativa contra incendis vigent i que es poden detectar mitjançant la funció inspectora atribuïda al personal competent de la Generalitat de Catalunya.»","§ accés exterior MAN.SP.000: «Accés per l’exterior: l’arribada dels bombers al sinistre El DB SI del CTE, en la secció SI 5, i el RSCIEI, en la secció 4 de l’annex II, regulen les condicions d’intervenció dels serveis d’extinció i salvament i l’accessibilitat des de l’exterior als edificis i establiments industrials.»","§ obertures d''accés MAN.SP.000: «Les obertures d’accés són forats en façana (portals i finestres, bàsicament) amb unes dimensions i separació regulades normativament.»","§ sector diferenciat MAN.SP.000: «Una altra via de penetració vàlida, però amb menor grau de seguretat són aquelles que es realitzen per un sector d’incendi diferenciat.»","§ aïllament tèrmic MAN.SP.000: «Aïllament tèrmic (I): el criteri d’aïllament tèrmic (I) es refereix a la capacitat d’un element constructiu de separació per impedir el pas de la calor durant un temps expressat en minuts, a partir dels resultats d’un assaig de resistència al foc.»","§ parets no portants MAN.SP.000: «Parets no portants entre sectors d’incendi: només han de garantir integritat i aïllament tèrmic (EI-t).»","§ ventilació de fums MAN.SP.000: «Sistemes de ventilació de fums d’incendi Els sistemes de ventilació de fums són instal·lacions que la normativa exigeix en alguns edificis i que disposen d’un conjunt d’obertures o equips mecànics d’extracció (ventiladors) per a l’evacuació de fums i gasos calents de la combustió d’un incendi, i si és el cas, d’obertures d’admissió d’aire net o equips mecànics d’aportació.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SP.000-Tema-23.-Prevencio-basica-incendis.pdf'), 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SP.000-Tema-23.-Prevencio-basica-incendis.pdf', null, null, null, null
  from public.topics t where t.slug = 'bomb-t23-prevencio-incendis'
