insert into public.sources (title, url, kind, publisher, published_on) values ('Cos de Bombers de la Generalitat · MAN.INES.000 Intervenció bàsica en incendis estructurals (Guia orientativa d''estudi, convocatòria 81/26)', 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-24-MAN.INES.000.pdf', 'web_oficial'::public.source_kind, 'Generalitat de Catalunya · Departament d''Interior i Seguretat Pública (DGPEIS)', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('bomb-t24-incendis-estructurals', 'Tema 24. Intervenció bàsica en incendis estructurals') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('bombers-generalitat') and t.slug = 'bomb-t24-incendis-estructurals' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"L''incendi estructural: repte i evolució constructiva"},{"n":"2","title":"Entorns d''intervenció: habitatges, comerços, indústries, centres singulars i subterranis"},{"n":"3","title":"Denominació de façanes (A, B, C, D)"},{"n":"4","title":"Valoració: estructura, plantes, accessibilitat, columna de fum, propagació i ocupants"},{"n":"5","title":"Maniobres d''extinció: interior, cabals i línies, control de gasos, atac transicional"},{"n":"6","title":"Control de la propagació"},{"n":"7","title":"Recerca i salvament: probabilitat de supervivència i tècniques de progressió"}]'::jsonb, '["§ complexitat MAN.INES.000: «Els incendis estructurals no només es caracteritzen pel seu potencial destructiu, sinó també per la complexitat de l''entorn en què es desenvolupen: espais tancats, compartimentats, sovint amb poca visibilitat, calor extrema i risc d’atrapament o col·lapse.»","§ subterranis MAN.INES.000: «Infraestructures subterrànies (aparcaments, túnels...) En túnels o galeries, cal tenir en compte la direcció de propagació dels fums.»","§ edificis nous MAN.INES.000: «Els més nous, en canvi, poden estar més compartimentats però incloure materials sintètics altament combustibles.»","§ convecció MAN.INES.000: «Propagació per fums calents (convecció) Els gasos calents i fums combustibles generats per l’incendi es mouen de forma convectiva cap a zones superiors, a través de forats, patis, escales i espais verticals.»","§ degoteig MAN.INES.000: «Propagació per degoteig (conducció vertical descendent) Un fenomen menys habitual però molt perillós és la propagació per degoteig de materials inflamats des de pisos superiors i que poden generar focus en les plantes inferiors.»","§ atac transicional MAN.INES.000: «No substitueix l’atac interior, sinó que el prepara i el fa més segur.»","§ paret guia MAN.INES.000: «Paret de referència (paret guia): un dels membres del binomi manté sempre contacte amb una paret o element fix.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-24-MAN.INES.000.pdf'), 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-24-MAN.INES.000.pdf', null, null, null, null
  from public.topics t where t.slug = 'bomb-t24-incendis-estructurals'
