insert into public.sources (title, url, kind, publisher, published_on) values ('Cos de Bombers de la Generalitat · MAN.INVE.000 Intervenció bàsica en incendis forestals (Guia orientativa d''estudi, convocatòria 81/26)', 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-25-MAN.INVE.000.pdf', 'web_oficial'::public.source_kind, 'Generalitat de Catalunya · Departament d''Interior i Seguretat Pública (DGPEIS)', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('bomb-t25-incendis-forestals', 'Tema 25. Intervenció bàsica en incendis forestals') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('bombers-generalitat') and t.slug = 'bomb-t25-incendis-forestals' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"Context: canvi del territori, abandonament rural i canvi climàtic"},{"n":"2","title":"Evolució històrica i paradoxa de l''extinció; generacions d''incendis i GRAF"},{"n":"3","title":"Parts de l''incendi: cap, flancs, cua, eix, perímetre i focus secundaris"},{"n":"4","title":"Classificació segons l''entorn i el tipus de propagació (superfície, capçades, subsòl)"},{"n":"5","title":"Patrons de propagació: vent, topogràfic i convectiu; tempestes"},{"n":"6","title":"Lectura de la columna de fum"},{"n":"7","title":"Sistema CPS i alineació de forces"}]'::jsonb, '["§ canvi del territori MAN.INVE.000: «L’augment de la superfície forestal, l’acumulació de combustible degut a l’abandonament del món rural i els efectes del canvi climàtic han provocat una escalada en la intensitat i la velocitat dels incendis, amb episodis de propagació extrema i períodes de risc crític cada cop més amplis.»","§ GIF superfície MAN.INVE.000: «No obstant això, aquesta eficàcia també provoca una acumulació de combustible que incrementa el risc i la intensitat dels grans incendis forestals, responsables de més del 90% de la superfície cremada total.»","§ GRAF MAN.INVE.000: «L’aportació del GRAF ha estat clau per a l’evolució del model català de gestió d’incendis forestals, passant d’un enfocament reactiu a un model proactiu i estratègic, on la lectura del foc, l’anàlisi del territori i la gestió preventiva són tan importants com l’extinció.»","§ cap MAN.INVE.000: «L’actuació directa sobre el cap és molt arriscada i sovint no recomanable.»","§ classificació per entorn MAN.INVE.000: «Per això, és útil aplicar una classificació que distingeixi entre incendis agrícoles, forestals, d’interfície urbana-forestal i de vegetació urbana.»","§ patró MAN.INVE.000: «El patró de propagació —sigui de vent, topogràfic o convectiu— ens indica quines són les forces principals que impulsen el comportament de les flames i, per tant, condiciona de manera directa la presa de decisions.»","§ tempestes MAN.INVE.000: «Les tempestes generen corrents ascendents intensos quan s’està desenvolupant la tempesta i ventades irregulars associades als corrents descendents, quan descarrega la tempesta, capaços de modificar en pocs minuts la direcció i la intensitat de la propagació del foc.»","§ alineació 0/3 MAN.INVE.000: «0/3: fora d’alineació – és el comportament mínim d’aquell incendi.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-25-MAN.INVE.000.pdf'), 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-25-MAN.INVE.000.pdf', null, null, null, null
  from public.topics t where t.slug = 'bomb-t25-incendis-forestals'
