insert into public.sources (title, url, kind, publisher, published_on) values ('Cos de Bombers de la Generalitat · MAN.INXX.000 Intervenció bàsica en incendis varis (Guia orientativa d''estudi, convocatòria 81/26)', 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.INXX.000-Tema-26-Prevencio-incendis-varis.pdf', 'web_oficial'::public.source_kind, 'Generalitat de Catalunya · Departament d''Interior i Seguretat Pública (DGPEIS)', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('bomb-t26-incendis-diversos', 'Tema 26. Intervenció bàsica en incendis diversos') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('bombers-generalitat') and t.slug = 'bomb-t26-incendis-diversos' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"Incendis de vehicles: definició, classificació i nous riscos"},{"n":"2","title":"Riscos: combustibles, sistemes pressuritzats, elèctrics i entorn viari"},{"n":"3","title":"Zonatge de seguretat i aproximació"},{"n":"4","title":"Maniobres estàndard i específiques segons la propulsió (benzina, dièsel, GLP, GNC, GNL, elèctrics)"},{"n":"5","title":"Incendis de contenidors: tipus, riscos i maniobres"},{"n":"6","title":"Altres incendis: vegetació urbana, pneumàtics i residus"}]'::jsonb, '["§ propulsió MAN.INXX.000: «Riscos segons el tipus de propulsió A més dels riscos generals, el tipus de combustible o sistema energètic condiciona significativament l’estratègia d’intervenció.»","§ riscos invisibles MAN.INXX.000: «El factor clau és identificar ràpidament el tipus de vehicle i el seu estat, mantenir distàncies de seguretat i protegir-nos sempre dels gasos i de les projeccions.»","§ zona d''autoprotecció MAN.INXX.000: «Zonatge de seguretat En qualsevol incendi de vehicle, el primer pas per garantir la seguretat és establir una zona d’autoprotecció al voltant del vehicle afectat.»","§ alta tensió MAN.INXX.000: «Riscos elèctrics L’increment de vehicles híbrids i elèctrics ha elevat el risc d’incidències associades a bateries d’alta tensió, que poden presentar reignició hores després de l’extinció del foc.»","§ benzina MAN.INXX.000: «Vehicles de benzina La benzina és extremadament volàtil: un dipòsit escalfat pot alliberar vapors inflamables i generar una deflagració sobtada.»","§ contenidors de superfície MAN.INXX.000: «Els contenidors de superfície són els més habituals en l’entorn urbà, i la inhalació dels fums d’aquest incendis representa un dels principals riscos tant per als bombers com per a la població general.»","§ remoure MAN.INXX.000: «Un cop el foc està controlat, és fonamental remoure el contingut amb eines manuals: els punts calents amagats poden fer una reignició si no es refreden bé.»","§ pneumàtics MAN.INXX.000: «Pneumàtics Els incendis de pneumàtics són especialment perillosos i persistents.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.INXX.000-Tema-26-Prevencio-incendis-varis.pdf'), 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.INXX.000-Tema-26-Prevencio-incendis-varis.pdf', null, null, null, null
  from public.topics t where t.slug = 'bomb-t26-incendis-diversos'
