insert into public.sources (title, url, kind, publisher, published_on) values ('Cos de Bombers de la Generalitat · MAN.RRTT.000 Intervenció bàsica en riscos NRBQ (Guia orientativa d''estudi, convocatòria 81/26)', 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.RRTT.000-Tema-27.-Intervencio-NRBQ.pdf', 'web_oficial'::public.source_kind, 'Generalitat de Catalunya · Departament d''Interior i Seguretat Pública (DGPEIS)', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('bomb-t27-riscos-nrbq', 'Tema 27. Intervenció bàsica en riscos NRBQ') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('bombers-generalitat') and t.slug = 'bomb-t27-riscos-nrbq' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"Concepte de risc NRBQ i fonts de risc a Catalunya"},{"n":"2","title":"Tipus d''accidents: químics, transport, fuites, reaccions i explosions"},{"n":"3","title":"Identificació: CLP, ADR, NFPA 704, formes de cisternes i detecció in situ"},{"n":"4","title":"Documentació complementària i personal tècnic"},{"n":"5","title":"Valoració: metodologia Font – Flux – Diana i metodologia inversa"},{"n":"6","title":"Maniobres defensives i ofensives: confinament, evacuació, contenció i mitigació"}]'::jsonb, '["§ radiació ionitzant MAN.RRTT.000: «Les conseqüències són especialment greus, amb gran alliberament de radiació ionitzant.»","§ reaccions MAN.RRTT.000: «Es produeixen quan dos o més productes químics incompatibles es combinen de forma accidental, generant calor, vapors tòxics, inflamacions o pressions inesperades.»","§ identificació MAN.RRTT.000: «La importància de la identificació En una emergència NRBQ, identificar ràpidament la substància o agent implicat és una de les primeres prioritats operatives.»","§ font MAN.RRTT.000: «Avaluar la font vol dir entendre quin és el risc inicial, la seva mida, naturalesa, estat físic i evolució prevista.»","§ dianes MAN.RRTT.000: «Entorn natural (rius, fauna, cultius…) L’objectiu principal és identificar i protegir aquestes dianes abans que pateixin les conseqüències del perill.»","§ ofensives MAN.RRTT.000: «Actuen principalment sobre el flux o sobre la font.»","§ confinament MAN.RRTT.000: «El confinament és especialment efectiu en incidents amb núvols tòxics lleugers i temporals.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.RRTT.000-Tema-27.-Intervencio-NRBQ.pdf'), 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.RRTT.000-Tema-27.-Intervencio-NRBQ.pdf', null, null, null, null
  from public.topics t where t.slug = 'bomb-t27-riscos-nrbq'
