insert into public.sources (title, url, kind, publisher, published_on) values ('Cos de Bombers de la Generalitat · MAN.SANI.000 Intervenció bàsica en assistència sanitària (Guia orientativa d''estudi, convocatòria 81/26)', 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SANI.000-Tema-28.-Assistencia-sanitaria.pdf', 'web_oficial'::public.source_kind, 'Generalitat de Catalunya · Departament d''Interior i Seguretat Pública (DGPEIS)', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('bomb-t28-assistencia-sanitaria', 'Tema 28. Intervenció bàsica en assistència sanitària') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('bombers-generalitat') and t.slug = 'bomb-t28-assistencia-sanitaria' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"L''assistència sanitària en emergències i el paper dels Bombers"},{"n":"2","title":"Cadena assistencial i contínuum assistencial"},{"n":"3","title":"Terminologia: SVB/SVA, urgència/emergència, signe/símptoma/síndrome, edat, anatomia i postures"},{"n":"4","title":"Tipus d''intervencions sanitàries de Bombers"},{"n":"5","title":"Valoració primària XABCDE: hemorràgia massiva, via aèria, respiració i circulació"},{"n":"6","title":"Constants: FR, SpO₂, pols, FC, ompliment capil·lar i pell"}]'::jsonb, '["§ difícil accés MAN.SANI.000: «Aquesta capacitat de Bombers de poder oferir una assistència sanitària en emergències és especialment rellevant en escenaris amb difícil accés per als serveis mèdics, com ara entorns de muntanya, aquàtics, incendis, accidents de trànsit, incidents amb múltiples afectats o catàstrofes.»","§ contínuum MAN.SANI.000: «L’objectiu és mantenir una continuïtat assistencial (contínuum assistencial) on cada esglaó reforça l’anterior i permet minimitzar el temps de resposta i maximitzar les possibilitats de supervivència i recuperació.»","§ suport vital MAN.SANI.000: «A continuació, es recullen alguns dels termes més rellevants: a) Suport Vital bàsic (SVB) i suport vital avançat (SVA) El suport vital és el conjunt de maniobres i tècniques destinades a mantenir les funcions vitals d’una persona davant d’una situació de risc imminent de mort.»","§ intern/extern MAN.SANI.000: «Intern/extern: més a prop o més lluny de la línia mitjana del cos.»","§ freqüència respiratòria MAN.SANI.000: «La freqüència respiratòria és el nombre de respiracions completes que fa un adult en un minut, i és un indicador essencial de l’efectivitat de la ventilació.»","§ musculatura accessòria MAN.SANI.000: «L’ús de musculatura accessòria (músculs del coll, espatlles i intercostals) i l’aleteig nasal mostra que el pacient fa un esforç extra per respirar, cosa que és un signe de compromís respiratori greu.»","§ saturació MAN.SANI.000: «La saturació d’oxigen mesura el percentatge d’hemoglobina que transporta oxigen a la sang i és un indicador directe de l’eficàcia de l’intercanvi gasós als pulmons.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SANI.000-Tema-28.-Assistencia-sanitaria.pdf'), 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SANI.000-Tema-28.-Assistencia-sanitaria.pdf', null, null, null, null
  from public.topics t where t.slug = 'bomb-t28-assistencia-sanitaria'
