insert into public.sources (title, url, kind, publisher, published_on) values ('Cos de Bombers de la Generalitat · MAN.SANI.001 Intervenció bàsica en incidents de múltiples víctimes (Guia orientativa d''estudi, convocatòria 81/26)', 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-29-MAN.SANI.001.pdf', 'web_oficial'::public.source_kind, 'Generalitat de Catalunya · Departament d''Interior i Seguretat Pública (DGPEIS)', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('bomb-t29-multiples-victimes', 'Tema 29. Intervenció bàsica en incidents de múltiples víctimes') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('bombers-generalitat') and t.slug = 'bomb-t29-multiples-victimes' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"Concepte d''IMV i característiques"},{"n":"2","title":"Objectiu de la intervenció i col·laboració entre serveis (APCAT, START)"},{"n":"3","title":"Classificació dels IMV segons la causa"},{"n":"4","title":"Triatge: concepte, mètode START, codis de colors i etiquetatge"},{"n":"5","title":"Triatge avançat META i altres mètodes"},{"n":"6","title":"Estructura operativa: activació, cèl·lula d''avaluació, comandament operatiu"},{"n":"7","title":"Zonatge, Àrea sanitària, CCA i evacuació hospitalària"}]'::jsonb, '["§ relació víctimes-recursos MAN.SANI.001: «És important entendre que el concepte d’IMV no depèn exclusivament del nombre de víctimes o afectats, sinó de la relació entre aquestes i els recursos presents o disponibles en aquell moment.»","§ benefici màxim MAN.SANI.001: «Objectiu de la intervenció En un IMV, no es tracta de salvar cada víctima per separat, sinó de prendre decisions que permetin obtenir el benefici més gran per al major nombre de persones.»","§ protocols MAN.SANI.001: «La col·laboració entre serveis es basa en protocols preestablerts com l’APCAT i el triatge START.»","§ verd MAN.SANI.001: «Verd (Prioritat 3): víctimes amb lesions lleus o ferides que poden esperar o rebre atenció ambulatòria.»","§ START a Catalunya MAN.SANI.001: «Altres mètodes de triatge El mètode START és el més utilitzat pels serveis d’emergència a Catalunya en les primeres fases d’un incident de múltiples víctimes.»","§ comandament integrat MAN.SANI.001: «És important recordar que el comandament operatiu no equival a lideratge total de l’emergència, sinó que forma part d’un model de comandament integrat, en què cada grup operatiu (bombers, SEM, policia) aporta el seu coneixement i capacitat d’actuació des de la seva responsabilitat.»","§ CCA MAN.SANI.001: «El Centre de Comandament Avançat (CCA) El Centre de Comandament Avançat és el punt de trobada dels comandaments dels diferents cossos que intervenen a l’incident.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-29-MAN.SANI.001.pdf'), 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-29-MAN.SANI.001.pdf', null, null, null, null
