insert into public.sources (title, url, kind, publisher, published_on) values ('Cos de Bombers de la Generalitat · MAN.SVES.000 Intervenció bàsica en estructures col·lapsades (Guia orientativa d''estudi, convocatòria 81/26)', 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-30-MAN.SVES.000.pdf', 'web_oficial'::public.source_kind, 'Generalitat de Catalunya · Departament d''Interior i Seguretat Pública (DGPEIS)', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('bomb-t30-estructures-collapsades', 'Tema 30. Intervenció bàsica en estructures col·lapsades') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('bombers-generalitat') and t.slug = 'bomb-t30-estructures-collapsades' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"Objectiu i marc: equips USAR, INSARAG, OSOCC i GREC"},{"n":"2","title":"Valoració del col·lapse estructural"},{"n":"3","title":"Tipus de col·lapse: total, parcial i secundari"},{"n":"4","title":"Recerca física: valoració inicial i crida i escolta"},{"n":"5","title":"Recerca instrumentalitzada i canina"},{"n":"6","title":"Apuntalaments: verticals, horitzontals i inclinats"},{"n":"7","title":"Senyalització de zones i de víctimes"}]'::jsonb, '["§ objectiu MAN.SVES.000: «L’objectiu principal és dotar els intervinents amb coneixements tècnics i pràctics bàsics que permetin actuar amb seguretat, eficiència i coordinació en escenaris complexos com ara ensorraments d’edificis, esllavissades o col·lapses estructurals derivats d’incendis, explosions o fenòmens naturals.»","§ INSARAG local MAN.SVES.000: «Els principis INSARAG són d’aplicació també a escala nacional i regional per millorar la coordinació entre bombers, protecció civil i serveis mèdics.»","§ col·lapse parcial MAN.SVES.000: «Col·lapses parcials Un col·lapse parcial es produeix quan només una part de l’estructura cedeix, ja sigui un mur, una coberta, un forjat o qualsevol altre element constructiu, mentre la resta de l’edificació roman aparentment estable.»","§ valoració inicial MAN.SVES.000: «Aquest procés ha de ser sistemàtic, progressiu i sempre subordinat a la seguretat dels intervinents.»","§ recerca canina MAN.SVES.000: «Canina La recerca canina és una maniobra de localització de víctimes atrapades que es basa en l’olfacte d’alt rendiment dels gossos ensinistrats, que treballen seguint l’olor humana emesa des de sota la runa o altres estructures col·lapsades.»","§ apuntalaments horitzontals MAN.SVES.000: «Apuntalaments horitzontals Els apuntalaments horitzontals són estructures provisionals dissenyades per estampar o sostenir murs que han perdut part de la seva resistència estructural des de l’exterior o assegurar parets de contenció i excavacions des de l’interior.»","§ senyalització MAN.SVES.000: «Senyalització La correcta senyalització de les zones en un escenari d’estructura col·lapsada és essencial per garantir la seguretat, l’eficàcia i la coordinació dels equips de rescat.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-30-MAN.SVES.000.pdf'), 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-30-MAN.SVES.000.pdf', null, null, null, null
  from public.topics t where t.slug = 'bomb-t30-estructures-collapsades'
