insert into public.sources (title, url, kind, publisher, published_on) values ('Cos de Bombers de la Generalitat · MAN.SVMN.000 Intervenció bàsica en salvaments al medi natural terrestre (Guia orientativa d''estudi, convocatòria 81/26)', 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-31-MAN.SVMN.000.pdf', 'web_oficial'::public.source_kind, 'Generalitat de Catalunya · Departament d''Interior i Seguretat Pública (DGPEIS)', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('bomb-t31-medi-natural-terrestre', 'Tema 31. Intervenció bàsica en salvaments al medi natural terrestre') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('bombers-generalitat') and t.slug = 'bomb-t31-medi-natural-terrestre' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"Concepte i àmbit del salvament al medi natural terrestre"},{"n":"2","title":"Recursos i coordinació: helicòpter, GRAE, unitats canines i altres cossos"},{"n":"3","title":"Característiques del medi i dificultats"},{"n":"4","title":"Meteorologia: variabilitat, tempestes, calor i fred"},{"n":"5","title":"Accés i logística d''evacuació"},{"n":"6","title":"Tipus d''intervenció: evacuacions, guiatges, rescats i recerques"},{"n":"7","title":"Maniobres bàsiques amb cordes: ancoratge, ràpel i ascens"}]'::jsonb, '["§ alta especialització MAN.SVMN.000: «Es tracta d’una tasca que moltes vegades requereix d’alta especialització, ja que sovint implica actuacions en condicions extremes: mal temps, poca visibilitat, risc de caigudes, llargs temps d''accés i escassetat de mitjans.»","§ meteorologia crítica MAN.SVMN.000: «Meteorologia: un factor clau i canviant en les operacions al medi natural En entorns de muntanya i zones naturals, la meteorologia és un factor crític que pot condicionar en gran mesura la seguretat, la rapidesa i fins i tot la viabilitat de la intervenció.»","§ accés MAN.SVMN.000: «Accés: una variable decisiva en la planificació i execució de la intervenció Un dels principals reptes de les intervencions en entorns naturals és la dificultat d''accés al lloc on es troba la víctima.»","§ vies d''escapament MAN.SVMN.000: «Definir diverses opcions d’accés i vies d’escapament, en cas que la principal esdevingui intransitable.»","§ rescats accessibles MAN.SVMN.000: «Rescats a) Rescats accessibles a peu o amb vehicle Hi ha situacions en què no és necessari un rescat tècnic, són intervencions que es poden portar a terme per una o més unitats bàsiques de bombers.»","§ avaluació de riscos MAN.SVMN.000: «Anticipació i avaluació de riscos Abans d’intervenir cal fer una avaluació contínua dels riscos, tant per als equips com per a la víctima.»","§ cordes MAN.SVMN.000: «Maniobres bàsiques amb cordes Les maniobres amb cordes són essencials en els rescats de muntanya i en qualsevol entorn vertical o de difícil accés.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-31-MAN.SVMN.000.pdf'), 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-31-MAN.SVMN.000.pdf', null, null, null, null
  from public.topics t where t.slug = 'bomb-t31-medi-natural-terrestre'
on conflict (topic_id, locale) do update
