insert into public.sources (title, url, kind, publisher, published_on) values ('Cos de Bombers de la Generalitat · MAN.SVVH.000 Intervenció bàsica en accidents de mobilitat viària (Guia orientativa d''estudi, convocatòria 81/26)', 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-32-MAN.SVVH.000.pdf', 'web_oficial'::public.source_kind, 'Generalitat de Catalunya · Departament d''Interior i Seguretat Pública (DGPEIS)', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('bomb-t32-accidents-mobilitat-viaria', 'Tema 32. Intervenció bàsica en accidents de mobilitat viària') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('bombers-generalitat') and t.slug = 'bomb-t32-accidents-mobilitat-viaria' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"Context de l''accidentalitat i concepte d''accident de mobilitat"},{"n":"2","title":"Parts dels vehicles i moviments: longitudinal, balanceig i capcineig"},{"n":"3","title":"Seguretat primària, secundària i terciària"},{"n":"4","title":"Autobusos i autocars; camions i vehicles pesants"},{"n":"5","title":"Accidents ferroviaris: tipus de trens, accés i riscos"},{"n":"6","title":"Valoració, posicions dels vehicles i tipus d''atrapament"},{"n":"7","title":"Biomecànica: energia de l''impacte i criteris d''alta energia"},{"n":"8","title":"Plans d''extracció (pla A, pla B, alliberament immediat)"}]'::jsonb, '["§ propulsió no convencional MAN.SVVH.000: «Aquesta realitat fa que els serveis d’emergència, especialment el Cos de Bombers, s’enfrontin a una tipologia d’accidents cada cop més variada i complexa, que pot implicar tant persones com mercaderies, amb risc afegit en cas de vehicles que transportin substàncies perilloses o utilitzin sistemes de propulsió no convencionals (com gas, electricitat o hidrogen).»","§ desplaçament longitudinal MAN.SVVH.000: «Desplaçament longitudinal És el moviment horitzontal endavant i endarrere en el sentit de la marxa.»","§ superestructura MAN.SVVH.000: «La superestructura és la part superior, on s’ubica l’habitacle de passatgers.»","§ tracció elèctrica MAN.SVVH.000: «Encara que el comboi sinistrat sembli aturat i la zona aparentment segura, cal obtenir confirmació oficial que la circulació ha estat tallada i que el sistema de tracció elèctrica està desconnectat.»","§ valoració MAN.SVVH.000: «Valoració La valoració és la fase prèvia i inicial de qualsevol intervenció en accidents de mobilitat.»","§ biomecànica MAN.SVVH.000: «Biomecànica de l’accident de trànsit La biomecànica de l’accident de trànsit és la ciència que, basant-se en la física i la medicina, estudia els mecanismes lesius d’un accident.»","§ pla B MAN.SVVH.000: «És l’opció prevista en paral·lel al Pla A, i es posa en marxa en cas que es produeixi un agreujament sobtat de l’estat de la víctima o una situació sobrevinguda que obligui a reduir el temps d’extracció de la persona afectada.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-32-MAN.SVVH.000.pdf'), 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-32-MAN.SVVH.000.pdf', null, null, null, null
  from public.topics t where t.slug = 'bomb-t32-accidents-mobilitat-viaria'
on conflict (topic_id, locale) do update
   set outline = excluded.outline, key_ideas = excluded.key_ideas, glossary = excluded.glossary,
       amendments = excluded.amendments, source_id = excluded.source_id, source_url = excluded.source_url,
