insert into public.sources (title, url, kind, publisher, published_on) values ('Cos de Bombers de la Generalitat · MAN.SVXX.000 Intervenció bàsica en rescat urbà (Guia orientativa d''estudi, convocatòria 81/26)', 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-33-MAN.SVXX.000.pdf', 'web_oficial'::public.source_kind, 'Generalitat de Catalunya · Departament d''Interior i Seguretat Pública (DGPEIS)', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('bomb-t33-rescat-urba', 'Tema 33. Intervenció bàsica en rescat urbà') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('bombers-generalitat') and t.slug = 'bomb-t33-rescat-urba' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"Concepte de rescat urbà i criteris d''accés"},{"n":"2","title":"Intervencions en alçada: procediment i marc normatiu"},{"n":"3","title":"Material: cordes, nusos, politges i ancoratges (SAS)"},{"n":"4","title":"Tècniques d''accés: escalada, ràpel, corda fixa i progressió amb MGO"},{"n":"5","title":"Evacuació: assegurament de víctimes, sistemes de politges, AEA i escales manuals"},{"n":"6","title":"Sistemes de protecció individual contra caigudes"}]'::jsonb, '["§ coneixement de l''entorn MAN.SVXX.000: «El coneixement de l’entorn urbà, les eines i les opcions d’entrada és essencial per prendre decisions eficients.»","§ alçada MAN.SVXX.000: «Inclouen totes aquelles actuacions on cal accedir, estabilitzar o evacuar persones situades en llocs elevats —cobertes, balcons, patis interiors, bastides, arbres, estructures metàl·liques, etc.—, i que suposen un risc de caiguda per a les víctimes o per als propis bombers.»","§ cordes MAN.SVXX.000: «Cordes Les cordes utilitzades en el treball en alçada són de tipus tècnic i estan fabricades amb materials sintètics d’alta resistència.»","§ ancoratges MAN.SVXX.000: «En entorns urbans és imprescindible saber identificar, crear i verificar ancoratges de fortuna segurs en estructures artificials.»","§ ràpel MAN.SVXX.000: «El ràpel és una tècnica que consisteix a baixar per una corda utilitzant un dispositiu de frenada, que permet controlar la velocitat de descens.»","§ AEA MAN.SVXX.000: «Consisteix a utilitzar l’AEA per accedir o fer el rescat de persones.»","§ protecció contra caigudes MAN.SVXX.000: «Sistemes de protecció individual contra caigudes Els sistemes de protecció individual contra caigudes són el conjunt de components previstos per protegir l’usuari contra les caigudes en alçada, que inclouen un dispositiu de subjecció del cos i un sistema de connexió que es fixa a un punt d’ancoratge segur.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-33-MAN.SVXX.000.pdf'), 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-33-MAN.SVXX.000.pdf', null, null, null, null
  from public.topics t where t.slug = 'bomb-t33-rescat-urba'
