insert into public.sources (title, url, kind, publisher, published_on) values ('Cos de Bombers de la Generalitat · MAN.SVMN.001 Intervenció bàsica en inundacions (Guia orientativa d''estudi, convocatòria 81/26)', 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SVMN.001-Tema-34.-Intervencio-en-inundacions.pdf', 'web_oficial'::public.source_kind, 'Generalitat de Catalunya · Departament d''Interior i Seguretat Pública (DGPEIS)', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('bomb-t34-inundacions', 'Tema 34. Intervenció bàsica en inundacions') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('bombers-generalitat') and t.slug = 'bomb-t34-inundacions' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"Impacte global de les inundacions i episodis a Catalunya"},{"n":"2","title":"Factors que afavoreixen les inundacions i canvi climàtic"},{"n":"3","title":"GRAE Subaquàtic"},{"n":"4","title":"Morfologia fluvial i tipus de cursos d''aigua"},{"n":"5","title":"Tipus d''inundacions i avingudes sobtades"},{"n":"6","title":"Zones inundables i període de retorn"},{"n":"7","title":"Valoració del risc: avisos, mapes i saturació del sòl"},{"n":"8","title":"Maniobres: buidatge, contenció, potabilització, recerca i rescat"}]'::jsonb, '["§ amenaça global MAN.SVMN.001: «Aquestes dades mostren que les inundacions no són només un problema local, sinó una amenaça global creixent, especialment en un context de canvi climàtic, urbanització accelerada i fragilitat dels ecosistemes.»","§ context mediterrani MAN.SVMN.001: «En el context mediterrani, amb pluges irregulars però molt intenses, aquests factors potencien encara més la vulnerabilitat del territori.»","§ capçalera MAN.SVMN.001: «Aquestes crescudes tenen una elevada capacitat d’arrossegament (pedres, fang, troncs) i el cabal pot augmentar en qüestió de minuts, amb risc d’avingudes fulminants.»","§ predicció MAN.SVMN.001: «El període de retorn no és una predicció, sinó una manera d’avaluar el risc.»","§ valoració MAN.SVMN.001: «Valoració del risc en inundacions Per garantir una intervenció eficaç i segura davant d’un episodi d’inundacions, cal fer una valoració prèvia acurada del risc i de l’escenari.»","§ potabilització MAN.SVMN.001: «Potabilització d’aigua En situacions d’emergència, quan l’aigua ha quedat contaminada o el subministrament habitual s’ha interromput, és essencial garantir aigua potable per a la població i per als serveis bàsics.»","§ rescat MAN.SVMN.001: «Maniobres de recerca i rescat en zones inundades El rescat de persones atrapades per una inundació és una de les actuacions més exigents i delicades per part dels cossos operatius.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SVMN.001-Tema-34.-Intervencio-en-inundacions.pdf'), 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SVMN.001-Tema-34.-Intervencio-en-inundacions.pdf', null, null, null, null
  from public.topics t where t.slug = 'bomb-t34-inundacions'
on conflict (topic_id, locale) do update
   set outline = excluded.outline, key_ideas = excluded.key_ideas, glossary = excluded.glossary,
       amendments = excluded.amendments, source_id = excluded.source_id, source_url = excluded.source_url,
       page_from = excluded.page_from, page_to = excluded.page_to, key_ideas_page = excluded.key_ideas_page
 where (n.outline, n.key_ideas, n.glossary, n.amendments)
       is distinct from (excluded.outline, excluded.key_ideas, excluded.glossary, excluded.amendments);
commit;
